# ==============================================================================
# TEXT HELPERS
# ==============================================================================
function Resolve-MenuText([string]$Raw) {
    if ([string]::IsNullOrWhiteSpace($Raw)) { return '' }
    $t = $Raw.Trim()
    if ($t.StartsWith('@')) {
        $t = [CME.Native]::LoadIndirect($t)
        if (-not $t) { return '' }
    }
    # Strip keyboard accelerators: "Open w&ith" -> "Open with", "A && B" -> "A & B"
    $t = $t.Replace('&&', [string][char]1).Replace('&', '').Replace([string][char]1, '&')
    return $t.Trim()
}

function Format-Identifier([string]$Id) {
    $t = $Id -replace '^[\d_]+', '' -replace '[_\.]+', ' '
    $t = [regex]::Replace($t, '(?<=[a-z0-9])(?=[A-Z])', ' ')
    $t = [regex]::Replace($t, '(?<=[A-Z])(?=[A-Z][a-z])', ' ')
    return $t.Trim()
}

function ConvertTo-Clsid([string]$Text) {
    if (-not $Text) { return $null }
    $m = [regex]::Match($Text, '[0-9A-Fa-f]{8}-(?:[0-9A-Fa-f]{4}-){3}[0-9A-Fa-f]{12}')
    if ($m.Success) { return '{' + $m.Value.ToUpperInvariant() + '}' }
    return $null
}

function ConvertTo-KeyName([string]$Name) {
    $k = $Name -replace '[^A-Za-z0-9]', ''
    if (-not $k) { $k = 'CustomCommand' }
    return $k
}

# ==============================================================================
# ICONS
# ==============================================================================
function Resolve-ExecutablePath([string]$Path) {
    if ([string]::IsNullOrWhiteSpace($Path)) { return $null }
    $p = [Environment]::ExpandEnvironmentVariables($Path.Trim().Trim('"'))
    if ($App.PathCache.ContainsKey($p)) { return $App.PathCache[$p] }

    $found = $null
    try {
        if ([IO.Path]::IsPathRooted($p)) {
            if ([IO.File]::Exists($p)) { $found = $p }
        } else {
            $names = @($p)
            if (-not [IO.Path]::HasExtension($p)) { $names += "$p.exe" }
            $dirs = @("$env:SystemRoot\System32", $env:SystemRoot) + ($env:PATH -split ';' | Where-Object { $_ })
            :outer foreach ($n in $names) {
                foreach ($d in $dirs) {
                    $c = Join-Path $d $n
                    if ([IO.File]::Exists($c)) { $found = $c; break outer }
                }
                foreach ($root in [Microsoft.Win32.Registry]::CurrentUser, [Microsoft.Win32.Registry]::LocalMachine) {
                    $k = $root.OpenSubKey("Software\Microsoft\Windows\CurrentVersion\App Paths\$n")
                    if ($k) {
                        $v = [string]$k.GetValue('')
                        $k.Close()
                        if ($v) {
                            $v = [Environment]::ExpandEnvironmentVariables($v.Trim('"'))
                            if ([IO.File]::Exists($v)) { $found = $v; break outer }
                        }
                    }
                }
            }
        }
    } catch {}
    $App.PathCache[$p] = $found
    return $found
}

function Get-ExeFromCommand([string]$Command) {
    if ([string]::IsNullOrWhiteSpace($Command)) { return '' }
    $c = $Command.Trim()
    if ($c.StartsWith('"')) {
        $end = $c.IndexOf('"', 1)
        if ($end -gt 1) { return $c.Substring(1, $end - 1) }
    }
    $m = [regex]::Match($c, '^(.+?\.(?:exe|com|bat|cmd))(?:\s|$)', 'IgnoreCase')
    if ($m.Success) { return $m.Groups[1].Value }
    return ($c -split '\s+')[0]
}

function Get-IconImage([string]$Spec) {
    if ([string]::IsNullOrWhiteSpace($Spec)) { return $null }
    if ($App.IconCache.ContainsKey($Spec)) { return $App.IconCache[$Spec] }

    $img = $null
    # "shell:<file>" and "ext:<.ext>" ask the shell for the icon Explorer itself shows
    if ($Spec -match '^(shell|ext):(.+)$') {
        $hIcon = [IntPtr]::Zero
        try {
            $hIcon = if ($Matches[1] -eq 'ext') { [CME.Native]::FileIcon("x$($Matches[2])", $true) } else { [CME.Native]::FileIcon($Matches[2], $false) }
            if ($hIcon -ne [IntPtr]::Zero) {
                $img = [System.Windows.Interop.Imaging]::CreateBitmapSourceFromHIcon(
                    $hIcon, [System.Windows.Int32Rect]::Empty, [System.Windows.Media.Imaging.BitmapSizeOptions]::FromEmptyOptions())
                $img.Freeze()
            }
        } catch { $img = $null }
        finally { if ($hIcon -ne [IntPtr]::Zero) { [void][CME.Native]::DestroyIcon($hIcon) } }
        $App.IconCache[$Spec] = $img
        return $img
    }
    try {
        $s = [Environment]::ExpandEnvironmentVariables($Spec.Trim()).TrimStart('@').Trim()
        $index = 0
        $m = [regex]::Match($s, '^(.*?),\s*(-?\d+)$')
        if ($m.Success) { $s = $m.Groups[1].Value; $index = [int]$m.Groups[2].Value }
        $path = Resolve-ExecutablePath $s
        if ($path) {
            if ($path -match '\.(png|jpe?g|bmp)$') {
                $bi = [System.Windows.Media.Imaging.BitmapImage]::new()
                $bi.BeginInit()
                $bi.UriSource = [Uri]::new($path)
                $bi.DecodePixelWidth = 40
                $bi.CacheOption = [System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad
                $bi.EndInit()
                $bi.Freeze()
                $img = $bi
            } else {
                $large = [IntPtr[]]::new(1)
                $n = [CME.Native]::ExtractIconEx($path, $index, $large, $null, 1)
                if ($n -gt 0 -and $n -ne [uint32]::MaxValue -and $large[0] -ne [IntPtr]::Zero) {
                    try {
                        $img = [System.Windows.Interop.Imaging]::CreateBitmapSourceFromHIcon(
                            $large[0], [System.Windows.Int32Rect]::Empty,
                            [System.Windows.Media.Imaging.BitmapSizeOptions]::FromEmptyOptions())
                        $img.Freeze()
                    } finally { [void][CME.Native]::DestroyIcon($large[0]) }
                }
            }
        }
    } catch { $img = $null }
    $App.IconCache[$Spec] = $img
    return $img
}

# ==============================================================================
# REGISTRY HELPERS
# ==============================================================================
function Get-HiveRoot([string]$Hive) {
    if ($Hive -eq 'HKLM') { return [Microsoft.Win32.Registry]::LocalMachine }
    return [Microsoft.Win32.Registry]::CurrentUser
}

function Copy-RegTree($Source, $Target) {
    foreach ($n in $Source.GetValueNames()) {
        $Target.SetValue($n, $Source.GetValue($n, $null, 'DoNotExpandEnvironmentNames'), $Source.GetValueKind($n))
    }
    foreach ($sub in $Source.GetSubKeyNames()) {
        $src = $Source.OpenSubKey($sub)
        $dst = $Target.CreateSubKey($sub)
        try { Copy-RegTree $src $dst } finally { $src.Close(); $dst.Close() }
    }
}

function Set-RegString($Key, [string]$Name, [string]$Value) {
    $kind = if ($Value -match '%[A-Za-z_][A-Za-z0-9_]*%') { 'ExpandString' } else { 'String' }
    $Key.SetValue($Name, $Value, [Microsoft.Win32.RegistryValueKind]$kind)
}

function Get-ClsidInfo([string]$Clsid) {
    if ($App.ClsidCache.ContainsKey($Clsid)) { return $App.ClsidCache[$Clsid] }
    $info = @{ Name = ''; Dll = ''; Registered = $true }
    try {
        $hkcr = [Microsoft.Win32.Registry]::ClassesRoot
        $k = $hkcr.OpenSubKey("CLSID\$Clsid")
        if (-not $k) {
            # Packaged COM and 32-bit-only registrations live elsewhere; only a CLSID found nowhere counts as unregistered.
            $alt = $hkcr.OpenSubKey("PackagedCom\ClassIndex\$Clsid")
            if (-not $alt) { $alt = $hkcr.OpenSubKey("WOW6432Node\CLSID\$Clsid") }
            if ($alt) { $alt.Close() } else { $info.Registered = $false }
        }
        if ($k) {
            $info.Name = Resolve-MenuText ([string]$k.GetValue(''))
            $ik = $k.OpenSubKey('InprocServer32')
            if ($ik) {
                $info.Dll = [Environment]::ExpandEnvironmentVariables([string]$ik.GetValue('')).Trim('"')
                $ik.Close()
            }
            $k.Close()
        }
    } catch {}
    $App.ClsidCache[$Clsid] = $info
    return $info
}

function Get-BlockedClsids {
    $res = @{}
    foreach ($hive in 'HKCU', 'HKLM') {
        $k = (Get-HiveRoot $hive).OpenSubKey($BlockedPath)
        if (-not $k) { continue }
        foreach ($n in $k.GetValueNames()) {
            $c = ConvertTo-Clsid $n
            if (-not $c) { continue }
            if (-not $res.ContainsKey($c)) { $res[$c] = @{} }
            $res[$c][$hive] = $n
        }
        $k.Close()
    }
    return $res
}

function Get-FileTypeBases([string]$Ext) {
    $ext = '.' + $Ext.Trim().TrimStart('.').ToLowerInvariant()
    $bases = [ordered]@{}
    $bases["SystemFileAssociations\$ext"] = "$ext files"
    $k = [Microsoft.Win32.Registry]::ClassesRoot.OpenSubKey($ext)
    if ($k) {
        $prog = [string]$k.GetValue('')
        $perceived = [string]$k.GetValue('PerceivedType')
        $k.Close()
        if ($prog) { $bases[$prog] = "$ext ($prog)" }
        if ($perceived) { $bases["SystemFileAssociations\$perceived"] = "All $perceived files" }
    }
    $uc = [Microsoft.Win32.Registry]::CurrentUser.OpenSubKey("Software\Microsoft\Windows\CurrentVersion\Explorer\FileExts\$ext\UserChoice")
    if ($uc) {
        $p = [string]$uc.GetValue('ProgId')
        $uc.Close()
        if ($p -and -not $bases.Contains($p)) { $bases[$p] = "$ext (default app)" }
    }
    return $bases
}

# ==============================================================================
# SCANNER
# ==============================================================================
function Complete-Entry([hashtable]$d) {
    $defaults = @{
        Id = ''; Kind = 'Command'; Name = ''; Sub = ''; KeyName = ''; Command = ''; IconValue = ''; IconSpec = ''
        Hive = 'HKCU'; BaseKey = ''; SubPath = ''; Paths = @(); LocIds = @(); LocLabel = ''; Enabled = $true
        IsBuiltIn = $false; Extended = $false; Shield = $false; Position = ''; Clsid = ''; Dll = ''; Package = ''
        BlockedNames = @{}; DashPaths = @(); Delegate = $false; Submenu = $false; ShellPath = ''
        ParentName = ''; ParentPath = ''; Children = 0; Broken = $false; BrokenReason = ''; Editable = $true
        FilePath = ''; Target = ''; Added = $false
    }
    foreach ($k in $defaults.Keys) { if (-not $d.ContainsKey($k)) { $d[$k] = $defaults[$k] } }

    $d.IsCommand  = $d.Kind -eq 'Command'
    $d.IsChild    = [bool]$d.ParentName
    $d.KindLabel  = switch ($d.Kind) {
        'Command'   { if ($d.Submenu) { 'Submenu' } else { 'Command' } }
        'Extension' { 'Shell extension' }
        'New'       { 'New menu item' }
        'SendTo'    { if ($d.Submenu) { 'Send to submenu' } else { 'Send to item' } }
        default     { 'Windows 11 menu' }
    }
    $d.KindTag    = switch ($d.Kind) {
        'Extension' { 'Extension' }
        'Modern'    { 'Win 11' }
        'New'       { '' }
        default     { if ($d.Submenu) { 'Submenu' } elseif ($d.ParentName) { "in $($d.ParentName)" } else { '' } }
    }
    $d.ScopeShort = switch ($d.Hive) { 'HKCU' { 'You' } 'HKLM' { 'All users' } default { 'App' } }
    $d.ScopeLabel = switch ($d.Hive) { 'HKCU' { 'Current user (HKCU)' } 'HKLM' { 'All users (HKLM)' } default { 'App package' } }
    if ($d.Kind -eq 'SendTo') { $d.ScopeLabel = 'Current user (Send To folder)' }
    $d.Glyph      = switch ($d.Kind) { 'Command' { $G.App } 'New' { $G.NewFile } 'SendTo' { $G.Send } default { $G.Puzzle } }
    $d.IconImage  = Get-IconImage $d.IconSpec
    # Submenus driven by ExtendedSubCommandsKey point elsewhere in the registry; only nested "shell" ones are editable here.
    $d.CanEdit    = $d.Kind -eq 'Command' -and $d.Editable
    $d.CanDelete  = $d.Kind -eq 'Command' -or $d.Kind -eq 'SendTo' -or ($d.Kind -eq 'Extension' -and $d.Broken) -or ($d.Kind -eq 'New' -and $d.Added)
    $d.CanRegedit = $d.Kind -ne 'Modern'

    $d.SearchText = (@($d.Name, $d.Sub, $d.KeyName, $d.Command, $d.Clsid, $d.Dll, $d.Package, $d.LocLabel, $d.ParentName) -join ' ').ToLowerInvariant()
    # Children sort directly under their submenu: group by parent name, parent first
    $d.GroupKey = if ($d.ParentName) { $d.ParentName } else { $d.Name }
    $d.ChildOrder = if ($d.ParentName) { 1 } else { 0 }
    return [pscustomobject]$d
}

# Label/value rows for the detail pane. Built on demand: doing it for every entry during a scan
# roughly doubled the scan time.
function Get-EntryDetails($d) {
    $flags = @()
    if ($d.Extended) { $flags += 'Only with Shift + right-click' }
    if ($d.Shield) { $flags += 'Shows UAC shield' }
    if ($d.Position) { $flags += "Pinned to $($d.Position.ToLower())" }
    if ($d.Submenu) { $flags += $(if ($d.Children) { "Submenu with $($d.Children) command$(if ($d.Children -ne 1) { 's' })" } else { 'Opens a submenu' }) }
    if ($d.ParentName) { $flags += "Inside the `"$($d.ParentName)`" submenu" }

    $menu = if (-not $App.IsWin11) { '' }
            elseif ($d.Kind -eq 'Modern' -or $d.Kind -eq 'New') { 'Main menu' }
            elseif ($App.Classic) { 'Main menu (classic menu is on)' }
            else { 'Under "Show more options"' }
    $hiveLong = if ($d.Hive -eq 'HKLM') { 'HKLM' } else { 'HKCU' }
    $regText = if ($d.Kind -eq 'SendTo') { '' } else { (@($d.Paths) | ForEach-Object { "$hiveLong\$_" }) -join "`n" }

    $det = [System.Collections.Generic.List[object]]::new()
    foreach ($f in @(
        @('Problem', $d.BrokenReason, $false),
        @('Appears on', $d.LocLabel, $false),
        @('Installed for', $d.ScopeLabel, $false),
        @('Windows 11', $menu, $false),
        @('Command', $d.Command, $true),
        @('Target', $d.Target, $true),
        @('File', $d.FilePath, $true),
        @('Icon', $d.IconValue, $true),
        @('Options', ($flags -join "`n"), $false),
        @('Package', $d.Package, $true),
        @('CLSID', $d.Clsid, $true),
        @('Handler DLL', $d.Dll, $true),
        @('Registry', $regText, $true)
    )) {
        if ($f[1]) { $det.Add([pscustomobject]@{ Label = $f[0]; Value = [string]$f[1]; Mono = $f[2]; Warn = $f[0] -eq 'Problem' }) }
    }
    return , $det
}

# True only for an absolute local path that is gone. Bare names (wt.exe), placeholders (%1),
# UNC paths and Store app folders are never reported, to avoid false alarms.
function Test-MissingFile([string]$Path) {
    if ([string]::IsNullOrWhiteSpace($Path)) { return $false }
    $p = [Environment]::ExpandEnvironmentVariables($Path.Trim().Trim('"'))
    if ($p.Contains('%') -or $p.StartsWith('\') -or $p -like '*\WindowsApps\*') { return $false }
    if (-not [IO.Path]::IsPathRooted($p)) { return $false }
    if ($App.MissingCache.ContainsKey($p)) { return $App.MissingCache[$p] }
    $missing = try { -not ([IO.File]::Exists($p) -or [IO.Directory]::Exists($p)) } catch { $false }
    $App.MissingCache[$p] = $missing
    return $missing
}

function Read-Verbs([string]$Hive, [string]$Base, $Info, $Out, [string]$ShellPath = '', [string]$ParentName = '', [string]$ParentPath = '') {
    if (-not $ShellPath) { $ShellPath = "Software\Classes\$Base\shell" }
    $pk = $null
    try { $pk = (Get-HiveRoot $Hive).OpenSubKey($ShellPath) } catch {}
    if (-not $pk) { return }
    try {
        foreach ($keyName in $pk.GetSubKeyNames()) {
            $vk = $null
            try { $vk = $pk.OpenSubKey($keyName) } catch {}
            if (-not $vk) { continue }
            try {
                $cmd = ''; $delegate = $false
                $ck = $vk.OpenSubKey('command')
                if ($ck) {
                    $cmd = [string]$ck.GetValue('', '', 'DoNotExpandEnvironmentNames')
                    $delegate = $null -ne $ck.GetValue('DelegateExecute')
                    $ck.Close()
                }
                $valueNames = $vk.GetValueNames()
                $raw = [string]$vk.GetValue('MUIVerb')
                if (-not $raw) { $raw = [string]$vk.GetValue('') }
                $name = Resolve-MenuText $raw
                if (-not $name) { $name = if ($KnownVerbNames.ContainsKey($keyName)) { $KnownVerbNames[$keyName] } else { Format-Identifier $keyName } }
                if (-not $name) { $name = $keyName }

                $iconValue = [string]$vk.GetValue('Icon', '', 'DoNotExpandEnvironmentNames')
                $nestedShell = $vk.GetSubKeyNames() -contains 'shell'
                $externalSub = ($valueNames -contains 'ExtendedSubCommandsKey') -or ([string]$vk.GetValue('SubCommands'))
                $submenu = $nestedShell -or $externalSub -or ($valueNames -contains 'SubCommands')
                $exe = Get-ExeFromCommand $cmd
                $iconSpec = if ($iconValue) { $iconValue } else { $exe }

                # Standard verbs (open/edit/print...) count as built-in even per-user: they are the
                # default app's own actions, not something added to the menu.
                $builtIn = $SystemVerbs.Contains($keyName)
                if ($Hive -eq 'HKLM' -and -not $builtIn) {
                    $exePath = Resolve-ExecutablePath $exe
                    $builtIn = $keyName -like 'Windows.*' -or (-not $cmd -and -not $submenu) -or
                               ($exePath -and $exePath.StartsWith($env:SystemRoot, [StringComparison]::OrdinalIgnoreCase) -and -not $iconValue)
                }

                $brokenReason = ''
                if ($cmd -and (Test-MissingFile $exe)) { $brokenReason = "Program not found: $([Environment]::ExpandEnvironmentVariables($exe))" }

                $subPath = "$ShellPath\$keyName"
                $childCount = 0
                if ($nestedShell -and -not $ParentName) {
                    $before = $Out.Count
                    Read-Verbs $Hive $Base $Info $Out "$subPath\shell" $name $subPath
                    $childCount = $Out.Count - $before
                }

                $sub = if ($cmd) { $cmd }
                       elseif ($submenu) { if ($childCount) { "Submenu with $childCount command$(if ($childCount -ne 1) { 's' })" } else { 'Submenu' } }
                       elseif ($delegate) { 'Built-in shell handler' } else { 'No command' }

                $Out.Add((Complete-Entry @{
                    Id = "cmd|$Hive|$subPath"; Kind = 'Command'; Name = $name; Sub = $sub; KeyName = $keyName
                    Command = $cmd; IconValue = $iconValue; IconSpec = $iconSpec; Hive = $Hive; BaseKey = $Base
                    ShellPath = $ShellPath; SubPath = $subPath; Paths = @($subPath); LocIds = $Info.Locs; LocLabel = $Info.Label
                    Enabled = -not (($valueNames -contains 'LegacyDisable') -or ($valueNames -contains 'ProgrammaticAccessOnly'))
                    IsBuiltIn = $builtIn; Extended = $valueNames -contains 'Extended'; Shield = $valueNames -contains 'HasLUAShield'
                    Position = [string]$vk.GetValue('Position'); Delegate = $delegate; Submenu = $submenu
                    Editable = -not ($submenu -and -not $nestedShell -and $externalSub)
                    ParentName = $ParentName; ParentPath = $ParentPath; Children = $childCount
                    Broken = [bool]$brokenReason; BrokenReason = $brokenReason
                }))
            } catch {
            } finally { $vk.Close() }
        }
    } finally { $pk.Close() }
}

function Read-Handlers([string]$Hive, [string]$Base, $Info, $Map) {
    $hPath = "Software\Classes\$Base\shellex\ContextMenuHandlers"
    $pk = $null
    try { $pk = (Get-HiveRoot $Hive).OpenSubKey($hPath) } catch {}
    if (-not $pk) { return }
    try {
        foreach ($keyName in $pk.GetSubKeyNames()) {
            $value = ''
            try {
                $hk = $pk.OpenSubKey($keyName)
                if ($hk) { $value = [string]$hk.GetValue(''); $hk.Close() }
            } catch {}
            $clsid = ConvertTo-Clsid $value
            if (-not $clsid) { $clsid = ConvertTo-Clsid $keyName }
            if (-not $clsid) { continue }

            $mapKey = "$Hive|$clsid"
            if (-not $Map.Contains($mapKey)) {
                $ci = Get-ClsidInfo $clsid
                $keyIsGuid = [bool](ConvertTo-Clsid $keyName)
                $name = if (-not $keyIsGuid) { $keyName } elseif ($ci.Name) { $ci.Name } else { 'Unknown extension' }
                $sub = if ($ci.Name -and $ci.Name -ne $name) { $ci.Name } elseif ($ci.Dll) { [IO.Path]::GetFileName($ci.Dll) } else { $clsid }
                $brokenReason = if (-not $ci.Registered) { "Handler $clsid is not registered (its program was probably uninstalled)" }
                                elseif (Test-MissingFile $ci.Dll) { "Handler DLL not found: $($ci.Dll)" } else { '' }
                $Map[$mapKey] = @{
                    Broken = [bool]$brokenReason; BrokenReason = $brokenReason
                    Id = "ext|$mapKey"; Kind = 'Extension'; Name = $name; Sub = $sub; KeyName = $keyName; Hive = $Hive
                    Clsid = $clsid; Dll = $ci.Dll; IconSpec = $ci.Dll; BaseKey = $Base
                    IsBuiltIn = ($Hive -eq 'HKLM') -and $ci.Dll -and $ci.Dll.StartsWith($env:SystemRoot, [StringComparison]::OrdinalIgnoreCase)
                    LocIdList = [System.Collections.Generic.List[string]]::new()
                    LabelList = [System.Collections.Generic.List[string]]::new()
                    PathList  = [System.Collections.Generic.List[string]]::new()
                    DashList  = [System.Collections.Generic.List[string]]::new()
                }
            }
            $e = $Map[$mapKey]
            foreach ($l in $Info.Locs) { if (-not $e.LocIdList.Contains($l)) { $e.LocIdList.Add($l) } }
            if (-not $e.LabelList.Contains($Info.Label)) { $e.LabelList.Add($Info.Label) }
            $e.PathList.Add("$hPath\$keyName")
            if ($value.StartsWith('-')) { $e.DashList.Add("$hPath\$keyName") }
        }
    } finally { $pk.Close() }
}

function Find-PackageAsset([string]$Root, [string]$Relative) {
    if (-not $Relative) { return $null }
    $full = Join-Path $Root $Relative
    if ([IO.File]::Exists($full)) { return $full }
    $dir = [IO.Path]::GetDirectoryName($full)
    if (-not [IO.Directory]::Exists($dir)) { return $null }
    $stem = [IO.Path]::GetFileNameWithoutExtension($full)
    $ext = [IO.Path]::GetExtension($full)
    $best = $null; $bestScore = -1
    foreach ($f in [IO.Directory]::GetFiles($dir, "$stem.*$ext")) {
        $n = [IO.Path]::GetFileName($f).ToLowerInvariant()
        if ($n.Contains('contrast-')) { continue }
        $score = 0
        if ($n.Contains('targetsize-32')) { $score += 6 } elseif ($n.Contains('targetsize-48')) { $score += 5 } elseif ($n.Contains('targetsize-24')) { $score += 4 }
        if ($n.Contains('unplated')) { $score += 2 }
        if ($n.Contains('scale-200')) { $score += 1 }
        if ($score -gt $bestScore) { $best = $f; $bestScore = $score }
    }
    return $best
}

function Resolve-PackageString([string]$FullName, [string]$Text) {
    if (-not $Text) { return '' }
    if ($Text.StartsWith('@')) { return [string][CME.Native]::LoadIndirect($Text) }
    if ($Text.StartsWith('ms-resource:')) {
        $pkg = $FullName.Split('_')[0]
        $res = $Text.Substring(12)
        $uri = if ($res.StartsWith('//')) { "ms-resource:$res" }
               elseif ($res.StartsWith('/')) { "ms-resource://$pkg$res" }
               elseif ($res.Contains('/')) { "ms-resource://$pkg/$res" }
               else { "ms-resource://$pkg/Resources/$res" }
        return [string][CME.Native]::LoadIndirect("@{$FullName?$uri}")
    }
    return $Text
}

# Packaged (MSIX) context menu entries. Manifests are parsed once per session; Refresh re-reads them.
function Get-PackagedRecords {
    if ($null -ne $App.Packaged) { return $App.Packaged }
    $list = [System.Collections.Generic.List[object]]::new()
    $seen = @{}
    $repo = 'Local Settings\Software\Microsoft\Windows\CurrentVersion\AppModel\Repository\Packages'
    $rk = $null
    try { $rk = [Microsoft.Win32.Registry]::ClassesRoot.OpenSubKey($repo) } catch {}
    if ($rk) {
        foreach ($full in $rk.GetSubKeyNames()) {
            try {
                $pk = $rk.OpenSubKey($full)
                $root = [string]$pk.GetValue('PackageRootFolder')
                $regName = [string]$pk.GetValue('DisplayName')
                $pk.Close()
                if (-not $root) { continue }
                $manifest = Join-Path $root 'AppxManifest.xml'
                if (-not [IO.File]::Exists($manifest)) { continue }
                $txt = [IO.File]::ReadAllText($manifest)
                if ($txt.IndexOf('fileExplorerContextMenus', [StringComparison]::OrdinalIgnoreCase) -lt 0) { continue }
                $x = [xml]$txt

                $appName = Resolve-PackageString $full $regName
                if (-not $appName) {
                    $node = $x.SelectSingleNode("//*[local-name()='Properties']/*[local-name()='DisplayName']")
                    if ($node) { $appName = Resolve-PackageString $full $node.InnerText }
                }
                if (-not $appName) { $appName = Format-Identifier (($full.Split('_')[0]) -replace '^.*\.', '') }

                $logo = $null
                $ve = $x.SelectSingleNode("//*[local-name()='VisualElements']")
                if ($ve -and $ve.GetAttribute('Square44x44Logo')) { $logo = Find-PackageAsset $root $ve.GetAttribute('Square44x44Logo') }
                if (-not $logo) {
                    $ln = $x.SelectSingleNode("//*[local-name()='Properties']/*[local-name()='Logo']")
                    if ($ln) { $logo = Find-PackageAsset $root $ln.InnerText }
                }

                $byClsid = [ordered]@{}
                foreach ($ext in $x.SelectNodes("//*[local-name()='Extension'][@Category='windows.fileExplorerContextMenus']")) {
                    foreach ($it in $ext.SelectNodes(".//*[local-name()='ItemType']")) {
                        foreach ($v in $it.SelectNodes("./*[local-name()='Verb']")) {
                            $clsid = ConvertTo-Clsid $v.GetAttribute('Clsid')
                            if (-not $clsid -or $seen.ContainsKey($clsid)) { continue }
                            if (-not $byClsid.Contains($clsid)) {
                                $byClsid[$clsid] = @{ Clsid = $clsid; VerbId = $v.GetAttribute('Id'); Types = [System.Collections.Generic.List[string]]::new() }
                            }
                            $t = $it.GetAttribute('Type')
                            if (-not $byClsid[$clsid].Types.Contains($t)) { $byClsid[$clsid].Types.Add($t) }
                        }
                    }
                }
                foreach ($r in $byClsid.Values) {
                    $seen[$r.Clsid] = $true
                    $r.App = $appName; $r.Logo = $logo; $r.Package = $full
                    $list.Add($r)
                }
            } catch {}
        }
        $rk.Close()
    }
    $App.Packaged = $list
    return $list
}

# ------------------------------------------------------------------------------
# "New" menu (ShellNew keys) and "Send to" (files in the SendTo folder)
# ------------------------------------------------------------------------------
$ShellNewBuiltIn = @('Folder', '.lnk', '.library-ms')

# Class keys that hold a ShellNew key (or our disabled _ShellNew). Walking all of HKCR takes ~250 ms,
# so the list is cached for the session; each scan only re-reads the state of these keys.
function Get-ShellNewParents {
    if ($null -ne $App.ShellNewParents) { return $App.ShellNewParents }
    $list = [System.Collections.Generic.List[string]]::new()
    $hkcr = [Microsoft.Win32.Registry]::ClassesRoot
    $skip = @('OpenWithProgids', 'OpenWithList', 'PersistentHandler', 'ShellEx')
    foreach ($ext in $hkcr.GetSubKeyNames()) {
        if (-not $ext.StartsWith('.')) { continue }
        $k = $null
        try { $k = $hkcr.OpenSubKey($ext) } catch {}
        if (-not $k) { continue }
        try {
            foreach ($sub in $k.GetSubKeyNames()) {
                if ($sub -eq 'ShellNew' -or $sub -eq '_ShellNew') { if (-not $list.Contains($ext)) { $list.Add($ext) }; continue }
                if ($skip -contains $sub) { continue }
                $s2 = $null
                try { $s2 = $k.OpenSubKey($sub) } catch {}
                if (-not $s2) { continue }
                foreach ($n in $s2.GetSubKeyNames()) { if ($n -eq 'ShellNew' -or $n -eq '_ShellNew') { $list.Add("$ext\$sub"); break } }
                $s2.Close()
            }
        } finally { $k.Close() }
    }
    $list.Add('Folder')
    $App.ShellNewParents = $list
    return $list
}

function Get-ProgIdName([string]$ProgId) {
    if (-not $ProgId) { return '' }
    $k = [Microsoft.Win32.Registry]::ClassesRoot.OpenSubKey($ProgId)
    if (-not $k) { return '' }
    try {
        $n = Resolve-MenuText ([string]$k.GetValue('FriendlyTypeName'))
        if (-not $n) { $n = Resolve-MenuText ([string]$k.GetValue('')) }
        return $n
    } finally { $k.Close() }
}

function Read-ShellNew($Out) {
    $hkcr = [Microsoft.Win32.Registry]::ClassesRoot
    foreach ($parent in (Get-ShellNewParents)) {
        foreach ($hive in 'HKCU', 'HKLM') {
            $pk = $null
            try { $pk = (Get-HiveRoot $hive).OpenSubKey("Software\Classes\$parent") } catch {}
            if (-not $pk) { continue }
            $names = $pk.GetSubKeyNames()
            $leaf = if ($names -contains 'ShellNew') { 'ShellNew' } elseif ($names -contains '_ShellNew') { '_ShellNew' } else { $null }
            $sk = if ($leaf) { $pk.OpenSubKey($leaf) } else { $null }
            $pk.Close()
            if (-not $sk) { continue }
            $vals = @{}
            foreach ($n in $sk.GetValueNames()) { $vals[$n.ToLowerInvariant()] = [string]$sk.GetValue($n, '', 'DoNotExpandEnvironmentNames') }
            $sk.Close()

            $ext = $parent.Split('\')[0]
            $progId = if ($parent.Contains('\')) { $parent.Split('\')[1] } elseif ($parent -eq 'Folder') { 'Folder' } else {
                $ek = $hkcr.OpenSubKey($ext)
                if ($ek) { [string]$ek.GetValue(''); $ek.Close() } else { '' }
            }
            $name = if ($vals.itemname) { Resolve-MenuText $vals.itemname } else { '' }
            if (-not $name) { $name = Get-ProgIdName $progId }
            if (-not $name) { $name = "$($ext.TrimStart('.').ToUpperInvariant()) file" }

            $how = if ($parent -eq 'Folder') { 'Creates a folder' }
                   elseif ($vals.ContainsKey('nullfile')) { 'Creates an empty file' }
                   elseif ($vals.filename) { 'Copies a template file' }
                   elseif ($vals.command) { 'Runs a program' }
                   elseif ($vals.ContainsKey('data')) { 'Creates a file from built-in data' }
                   else { 'Built-in handler' }
            $broken = ''
            if ($vals.filename -and (Test-MissingFile $vals.filename)) { $broken = "Template file not found: $($vals.filename)" }
            elseif ($vals.command -and (Test-MissingFile (Get-ExeFromCommand $vals.command))) { $broken = "Program not found: $(Get-ExeFromCommand $vals.command)" }

            $Out.Add((Complete-Entry @{
                Id = "new|$hive|$parent"; Kind = 'New'; Name = $name; Sub = $(if ($parent -eq 'Folder') { $how } else { "$ext  /  $how" })
                KeyName = $ext; Hive = $hive; SubPath = "Software\Classes\$parent\$leaf"; Paths = @("Software\Classes\$parent\$leaf")
                LocIds = @('newmenu'); LocLabel = 'New menu'; Enabled = $leaf -eq 'ShellNew'; IsBuiltIn = $ShellNewBuiltIn -contains $parent
                IconSpec = $(if ($vals.iconpath) { $vals.iconpath } elseif ($parent -eq 'Folder') { 'imageres.dll,-3' } else { "ext:$ext" })
                Command = [string]$vals.command; Target = [string]$vals.filename; Added = $vals.ContainsKey('cmeadded')
                Broken = [bool]$broken; BrokenReason = $broken
            }))
        }
    }
}

function Get-SendToDir { return [Environment]::GetFolderPath('SendTo') }

function Get-Wsh {
    if (-not $App.Wsh) { $App.Wsh = New-Object -ComObject WScript.Shell }
    return $App.Wsh
}

function Get-SendToFileInfo([IO.FileInfo]$File) {
    # Shell display names and shortcut targets are slow to read; cache them per file version.
    $cacheKey = "$($File.FullName)|$($File.LastWriteTimeUtc.Ticks)"
    if (-not $App.SendToCache.ContainsKey($cacheKey)) {
        $info = @{ Name = [CME.Native]::DisplayName($File.FullName); Target = ''; Arguments = ''; Description = '' }
        if ($File.Extension -ieq '.lnk') {
            try {
                $sc = (Get-Wsh).CreateShortcut($File.FullName)
                $info.Target = [string]$sc.TargetPath
                $info.Arguments = [string]$sc.Arguments
                $info.Description = [string]$sc.Description
            } catch {}
        }
        $App.SendToCache[$cacheKey] = $info
    }
    return $App.SendToCache[$cacheKey]
}

function New-SendToFileEntry([IO.FileInfo]$File, [string]$RelPath, [string]$ParentName, [string]$ParentPath) {
    $info = Get-SendToFileInfo $File
    $name = if ($info.Name) { $info.Name } else { $File.BaseName }
    $target = $info.Target; $arguments = $info.Arguments; $broken = ''
    if ($target -and (Test-MissingFile $target)) { $broken = "Shortcut target not found: $target" }
    $sub = if ($target -like '*\CmeSendTo.exe') { if ($info.Description) { $info.Description } else { 'Windows 11 menu command' } }
           elseif ($target) { $target } else {
        switch ($File.Extension.ToLowerInvariant()) {
            '.zfsendtotarget' { 'Built-in: add to a zip file' }
            '.desklink'       { 'Built-in: shortcut on the desktop' }
            '.mapimail'       { 'Built-in: attach to an e-mail' }
            default           { $File.Name }
        }
    }
    return Complete-Entry @{
        Id = "sendto|$RelPath"; Kind = 'SendTo'; Name = $name; Sub = $sub; KeyName = $RelPath; Hive = 'HKCU'
        Paths = @($File.FullName); FilePath = $File.FullName; Target = ((@($target, $arguments) | Where-Object { $_ }) -join ' ')
        LocIds = @('sendto'); LocLabel = 'Send to'; IconSpec = "shell:$($File.FullName)"
        Enabled = -not ($File.Attributes -band [IO.FileAttributes]::Hidden)
        Broken = [bool]$broken; BrokenReason = $broken; ParentName = $ParentName; ParentPath = $ParentPath
    }
}

# Files in the Send To folder are menu items; subfolders show up as submenus of their contents.
function Read-SendTo($Out) {
    $dir = Get-SendToDir
    if (-not $dir -or -not (Test-Path -LiteralPath $dir)) { return }
    foreach ($f in Get-ChildItem -LiteralPath $dir -Force -ErrorAction SilentlyContinue) {
        if ($f.Name -ieq 'desktop.ini') { continue }
        if (-not $f.PSIsContainer) {
            $Out.Add((New-SendToFileEntry $f $f.Name '' ''))
            continue
        }
        $children = @(Get-ChildItem -LiteralPath $f.FullName -Force -File -ErrorAction SilentlyContinue | Where-Object { $_.Name -ine 'desktop.ini' })
        foreach ($c in $children) { $Out.Add((New-SendToFileEntry $c "$($f.Name)\$($c.Name)" $f.Name $f.FullName)) }
        $Out.Add((Complete-Entry @{
            Id = "sendto|$($f.Name)"; Kind = 'SendTo'; Name = $f.Name; KeyName = $f.Name; Hive = 'HKCU'
            Sub = "Submenu with $($children.Count) item$(if ($children.Count -ne 1) { 's' })"
            Paths = @($f.FullName); FilePath = $f.FullName; LocIds = @('sendto'); LocLabel = 'Send to'; IconSpec = "shell:$($f.FullName)"
            Enabled = -not ($f.Attributes -band [IO.FileAttributes]::Hidden); Submenu = $true; Children = $children.Count
        }))
    }
}

function Rename-RegKey([string]$Hive, [string]$SubPath, [string]$NewLeaf) {
    $i = $SubPath.LastIndexOf('\')
    $leaf = $SubPath.Substring($i + 1)
    if ($leaf -eq $NewLeaf) { return }
    $parent = (Get-HiveRoot $Hive).OpenSubKey($SubPath.Substring(0, $i), $true)
    if (-not $parent) { throw "Registry key no longer exists: $SubPath" }
    try {
        $src = $parent.OpenSubKey($leaf)
        if (-not $src) { throw "Registry key no longer exists: $SubPath" }
        $dst = $parent.CreateSubKey($NewLeaf)
        try { Copy-RegTree $src $dst } finally { $src.Close(); $dst.Close() }
        $parent.DeleteSubKeyTree($leaf, $false)
    } finally { $parent.Close() }
}

# Adds "New > <type>" (creates an empty file). Returns @{ Hive; SubPath } of the created key.
# Uses HKCU only when the user already has their own key for the extension; creating a fresh
# HKCU\Software\Classes\.ext could shadow the machine-wide association, so otherwise it goes to HKLM.
function Add-ShellNewType([string]$Ext) {
    $ext = '.' + $Ext.Trim().TrimStart('.').ToLowerInvariant()
    if ($ext -match '[^.a-z0-9_+-]' -or $ext -eq '.') { throw 'Enter a file extension such as .txt' }
    $hkcr = [Microsoft.Win32.Registry]::ClassesRoot
    $ek = $hkcr.OpenSubKey($ext)
    $progId = if ($ek) { [string]$ek.GetValue('') } else { '' }
    $existing = if ($ek) { $ek.GetSubKeyNames() } else { @() }
    if ($ek) { $ek.Close() }
    if (-not $progId -or -not (Get-ProgIdName $progId)) {
        throw "Windows names New menu items after the file type's registered program (ProgID), and $ext has none on this PC (its ProgID is '$progId'). Install or set a default app for $ext first."
    }
    if ($existing -contains 'ShellNew') { throw "$ext is already in the New menu." }
    if ($existing -contains '_ShellNew') { throw "$ext is already in the list, turned off. Switch it back on instead." }

    $userKey = [Microsoft.Win32.Registry]::CurrentUser.OpenSubKey("Software\Classes\$ext")
    $hive = if ($userKey) { $userKey.Close(); 'HKCU' } else { 'HKLM' }
    $subPath = "Software\Classes\$ext\ShellNew"
    $k = (Get-HiveRoot $hive).CreateSubKey($subPath)
    try {
        $k.SetValue('NullFile', '')
        $k.SetValue('CMEAdded', '1')
    } finally { $k.Close() }
    if ($App.ShellNewParents -and -not $App.ShellNewParents.Contains($ext)) { $App.ShellNewParents.Add($ext) }
    return @{ Hive = $hive; SubPath = $subPath }
}

# Creates a shortcut in the SendTo folder. Returns its path.
function Add-SendToShortcut([string]$Target) {
    $dir = Get-SendToDir
    $name = if (Test-Path -LiteralPath $Target -PathType Container) { Split-Path -Leaf $Target } else {
        $desc = try { [Diagnostics.FileVersionInfo]::GetVersionInfo($Target).FileDescription } catch { '' }
        if ($desc) { $desc } else { [IO.Path]::GetFileNameWithoutExtension($Target) }
    }
    $name = $name -replace '[\\/:*?"<>|]', '_'
    $path = Join-Path $dir "$name.lnk"
    $i = 2
    while (Test-Path -LiteralPath $path) { $path = Join-Path $dir "$name ($i).lnk"; $i++ }
    $sc = (Get-Wsh).CreateShortcut($path)
    $sc.TargetPath = $Target
    $sc.Save()
    return $path
}

# ------------------------------------------------------------------------------
# "Add to Send to": turns an existing right-click entry into a Send To shortcut that runs the same thing.
#   - Commands whose file argument comes last ("app.exe -x "%1"") become a plain shortcut to app.exe -x;
#     Send To appends the selected paths, which is what %1 would have been.
#   - Windows 11 menu items (IExplorerCommand COM handlers, e.g. Blip) have no command line, so the
#     shortcut points at a tiny bridge program that invokes the same handler on the files, as Explorer does.
#     The bridge is compiled from the C# below on first use (Windows PowerShell's Add-Type can emit an
#     .exe; PowerShell 7's cannot) into %LOCALAPPDATA%\ContextMenuEditor, so shortcuts keep working if
#     this editor's folder moves.
# ------------------------------------------------------------------------------

function Get-BridgeDir { return Join-Path $env:LOCALAPPDATA 'ContextMenuEditor' }

# Builds CmeSendTo.exe if it is missing or older than the source above. Returns its path.
function Install-SendToBridge {
    $dir = Get-BridgeDir
    $exe = Join-Path $dir 'CmeSendTo.exe'
    $stamp = Join-Path $dir 'CmeSendTo.version'
    $sha = [Security.Cryptography.SHA256]::Create()
    $hash = [BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($BridgeSource))).Replace('-', '')
    if ((Test-Path -LiteralPath $exe) -and (Test-Path -LiteralPath $stamp) -and ([IO.File]::ReadAllText($stamp).Trim() -eq $hash)) { return $exe }

    if (-not (Test-Path -LiteralPath $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
    $src = Join-Path $dir 'CmeSendTo.cs'
    [IO.File]::WriteAllText($src, $BridgeSource, [Text.UTF8Encoding]::new($false))
    $build = "Add-Type -TypeDefinition ([IO.File]::ReadAllText('$($src.Replace("'", "''"))')) -OutputAssembly '$($exe.Replace("'", "''"))' -OutputType WindowsApplication"
    $psi = [Diagnostics.ProcessStartInfo]::new("$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe")
    $psi.Arguments = '-NoProfile -NonInteractive -ExecutionPolicy Bypass -EncodedCommand ' + [Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($build))
    $psi.UseShellExecute = $false
    $psi.CreateNoWindow = $true
    $psi.RedirectStandardError = $true
    # A PowerShell 7 parent leaks its module path into the child, which breaks Windows PowerShell's own modules.
    $psi.EnvironmentVariables['PSModulePath'] = "$env:ProgramFiles\WindowsPowerShell\Modules;$env:SystemRoot\System32\WindowsPowerShell\v1.0\Modules"
    $p = [Diagnostics.Process]::Start($psi)
    $err = $p.StandardError.ReadToEnd()
    $p.WaitForExit()
    if ($p.ExitCode -ne 0 -or -not (Test-Path -LiteralPath $exe)) { throw "Could not build the Send To bridge. $err" }
    [IO.File]::WriteAllText($stamp, $hash)
    return $exe
}

# Lists what a Windows 11 menu handler offers for a file: @{ Title; Index; Flags; State } per top-level subcommand,
# or a single entry for the handler itself when it has no submenu.
function Get-ExplorerCommandItems([string]$Clsid) {
    $exe = Install-SendToBridge
    $sample = Join-Path $env:TEMP 'Document.txt'
    if (-not (Test-Path -LiteralPath $sample)) { [IO.File]::WriteAllText($sample, '') }
    $out = Join-Path $env:TEMP "cme-probe-$([guid]::NewGuid().ToString('N')).txt"
    try {
        $p = Start-Process -FilePath $exe -ArgumentList @('--probe', $Clsid, "`"$out`"", "`"$sample`"") -PassThru -Wait -WindowStyle Hidden
        if (-not (Test-Path -LiteralPath $out)) { throw 'The menu handler could not be loaded.' }
        $lines = [IO.File]::ReadAllLines($out, [Text.Encoding]::UTF8)
    } finally { Remove-Item -LiteralPath $out -Force -ErrorAction SilentlyContinue }

    $top = [regex]::Match($lines[0], '^title=(.*)\|flags=(\d+)\|state=(\d+)$')
    $items = foreach ($l in $lines) {
        $m = [regex]::Match($l, '^  \[(\d+)\] {3}title=(.*)\|flags=(\d+)\|state=(\d+)$')
        if ($m.Success) { @{ Index = [int]$m.Groups[1].Value; Title = $m.Groups[2].Value; Flags = [int]$m.Groups[3].Value; State = [int]$m.Groups[4].Value } }
    }
    return @{ Title = $top.Groups[1].Value; Flags = [int]$top.Groups[2].Value; Subs = @($items) }
}

# "app.exe" -x "%1"  ->  @{ Target = app.exe; Arguments = -x }, or $null when the file argument isn't last.
function ConvertTo-SendToCommand([string]$Command) {
    if (-not $Command) { return $null }
    $m = [regex]::Match($Command.Trim(), '^(?<pre>.*?)\s*"?%[1LlVv*]"?$')
    if (-not $m.Success) { return $null }
    $pre = $m.Groups['pre'].Value.Trim()
    if (-not $pre -or $pre -match '%[1LlVvWw*]') { return $null }
    $exe = Get-ExeFromCommand $pre
    $rest = if ($pre.StartsWith('"')) { $pre.Substring([Math]::Min($pre.Length, $exe.Length + 2)) } else { $pre.Substring($exe.Length) }
    return @{ Target = [Environment]::ExpandEnvironmentVariables($exe); Arguments = $rest.Trim() }
}

function Test-CanSendTo($Item) {
    if ($Item.Kind -eq 'Modern') { return $true }
    if ($Item.Kind -ne 'Command') { return $false }
    if ($Item.Submenu) { return [bool]($App.Items | Where-Object { $_.ParentPath -eq $Item.SubPath -and (ConvertTo-SendToCommand $_.Command) }) }
    return [bool](ConvertTo-SendToCommand $Item.Command)
}

# Windows only reads .ico/.exe/.dll icons for shortcuts; packaged apps ship PNG logos, so wrap the PNG in an
# .ico (Vista+ icons may contain PNG data as-is).
function ConvertTo-IcoFile([string]$Png, [string]$Ico) {
    $bytes = [IO.File]::ReadAllBytes($Png)
    if ($bytes.Length -lt 24 -or $bytes[0] -ne 0x89 -or $bytes[1] -ne 0x50) { return $false }
    $w = ([int]$bytes[16] -shl 24) -bor ([int]$bytes[17] -shl 16) -bor ([int]$bytes[18] -shl 8) -bor [int]$bytes[19]
    $h = ([int]$bytes[20] -shl 24) -bor ([int]$bytes[21] -shl 16) -bor ([int]$bytes[22] -shl 8) -bor [int]$bytes[23]
    $ms = [IO.MemoryStream]::new()
    $bw = [IO.BinaryWriter]::new($ms)
    $bw.Write([uint16]0); $bw.Write([uint16]1); $bw.Write([uint16]1)
    $bw.Write([byte]$(if ($w -ge 256) { 0 } else { $w })); $bw.Write([byte]$(if ($h -ge 256) { 0 } else { $h }))
    $bw.Write([byte]0); $bw.Write([byte]0); $bw.Write([uint16]1); $bw.Write([uint16]32)
    $bw.Write([uint32]$bytes.Length); $bw.Write([uint32]22); $bw.Write($bytes)
    $bw.Flush()
    [IO.File]::WriteAllBytes($Ico, $ms.ToArray())
    return $true
}

# What "Add to Send to" can create for an entry: a list of @{ Name; Target; Arguments; Icon; Description }.
# Throws with a readable reason when the entry can't work from Send To.
function Get-SendToOptions($Item) {
    $opts = [System.Collections.Generic.List[object]]::new()
    if ($Item.Kind -eq 'Command') {
        $sources = if ($Item.Submenu) { @($App.Items | Where-Object { $_.ParentPath -eq $Item.SubPath } | Sort-Object Name) } else { @($Item) }
        foreach ($s in $sources) {
            $c = ConvertTo-SendToCommand $s.Command
            if (-not $c) { continue }
            $name = if ($s.ParentName) { "$($s.ParentName) - $($s.Name)" } else { $s.Name }
            $icon = if ($s.IconValue) { $s.IconValue } elseif ($Item.IconValue) { $Item.IconValue } else { "$($c.Target),0" }
            $opts.Add(@{ Name = $name; Target = $c.Target; Arguments = $c.Arguments; Icon = $icon; Description = "$name (from the right-click menu)"
                         Group = $(if ($Item.Submenu) { $Item.Name } else { '' }); Short = $s.Name
                         GroupIcon = $(if ($Item.IconValue) { $Item.IconValue } else { $icon }) })
        }
        if (-not $opts.Count) {
            throw 'Send To adds the selected files to the end of the command, but this command needs the file somewhere else (or takes no file), so it would not work the same way.'
        }
        return , $opts.ToArray()
    }
    if ($Item.Kind -ne 'Modern') { throw 'Only commands and Windows 11 menu items can be added to Send To.' }

    $exe = Install-SendToBridge
    $probe = Get-ExplorerCommandItems $Item.Clsid
    $icon = ''
    if ($Item.IconSpec -and $Item.IconSpec -match '\.png$' -and (Test-Path -LiteralPath $Item.IconSpec)) {
        $iconDir = Join-Path (Get-BridgeDir) 'icons'
        if (-not (Test-Path -LiteralPath $iconDir)) { New-Item -ItemType Directory -Path $iconDir -Force | Out-Null }
        $ico = Join-Path $iconDir (($Item.Name -replace '[\\/:*?"<>|]', '_') + '.ico')
        if (ConvertTo-IcoFile $Item.IconSpec $ico) { $icon = "$ico,0" }
    }
    $appName = if ($probe.Title) { $probe.Title } else { $Item.Name }
    # Subcommand flags: 0x1 has its own submenu, 0x8 separator; state 0x2 hidden.
    $subs = @($probe.Subs | Where-Object { -not ($_.Flags -band 0x8) -and -not ($_.Flags -band 0x1) -and -not ($_.State -band 0x2) -and $_.Title })
    if ($probe.Flags -band 0x1) {
        if (-not $subs) { throw "$appName shows nothing for files right now, so there is nothing to add." }
        foreach ($s in $subs) {
            $title = $s.Title.TrimEnd('.').Trim()
            $route = "$($s.Index):$($s.Title)".Replace('"', "'")
            $opts.Add(@{ Name = "$appName - $title"; Target = $exe; Arguments = "$($Item.Clsid) --sub `"$route`""; Icon = $icon
                         Description = "$appName > $($s.Title) (Windows 11 menu command)"; Group = $appName; Short = $title; GroupIcon = $icon })
        }
    } else {
        $opts.Add(@{ Name = $appName; Target = $exe; Arguments = $Item.Clsid; Icon = $icon; Description = "$appName (Windows 11 menu command)"; Group = ''; Short = $appName })
    }
    return , $opts.ToArray()
}

# A subfolder of Send To shows as a submenu. Creates it if needed, with the app's icon via desktop.ini
# (Windows only reads desktop.ini in folders marked read-only or system). Returns @{ Path; Created }.
function Initialize-SendToFolder([string]$Name, [string]$Icon) {
    $path = Join-Path (Get-SendToDir) ($Name -replace '[\\/:*?"<>|]', '_')
    if (Test-Path -LiteralPath $path -PathType Container) { return @{ Path = $path; Created = $false } }
    New-Item -ItemType Directory -Path $path -Force | Out-Null
    if ($Icon) {
        $res = [Environment]::ExpandEnvironmentVariables($Icon)
        if ($res -notmatch ',\s*-?\d+$') { $res = "$res,0" }
        $ini = Join-Path $path 'desktop.ini'
        [IO.File]::WriteAllText($ini, "[.ShellClassInfo]`r`nIconResource=$res`r`n", [Text.Encoding]::Unicode)
        (Get-Item -LiteralPath $ini -Force).Attributes = 'Hidden, System'
        $dir = Get-Item -LiteralPath $path -Force
        $dir.Attributes = $dir.Attributes -bor [IO.FileAttributes]::ReadOnly
    }
    return @{ Path = $path; Created = $true }
}

# Puts a Send To shortcut for $Option in place, inside its submenu folder when $Grouped.
# An identical shortcut elsewhere in Send To (say a flat "Blip - Laptop" from before) is moved instead of duplicated.
# Returns @{ Action = 'created' | 'moved' | 'exists'; Path; From }.
function New-SendToShortcut($Option, [switch]$Grouped) {
    $root = Get-SendToDir
    $useGroup = $Grouped -and $Option.Group
    $dir = if ($useGroup) { (Initialize-SendToFolder $Option.Group $Option.GroupIcon).Path } else { $root }
    $name = $(if ($useGroup) { $Option.Short } else { $Option.Name }) -replace '[\\/:*?"<>|]', '_'

    $candidates = @(Get-ChildItem -LiteralPath $root -Filter *.lnk -Force -ErrorAction SilentlyContinue) +
                  @(Get-ChildItem -LiteralPath $root -Directory -Force -ErrorAction SilentlyContinue | ForEach-Object { Get-ChildItem -LiteralPath $_.FullName -Filter *.lnk -Force -ErrorAction SilentlyContinue })
    foreach ($f in $candidates) {
        $sc = $null
        try { $sc = (Get-Wsh).CreateShortcut($f.FullName) } catch {}
        if (-not $sc -or $sc.TargetPath -ne $Option.Target -or $sc.Arguments -ne $Option.Arguments) { continue }
        if ($f.DirectoryName -eq $dir) { return @{ Action = 'exists'; Path = $f.FullName } }
        $to = Join-Path $dir "$name.lnk"
        $i = 2
        while (Test-Path -LiteralPath $to) { $to = Join-Path $dir "$name ($i).lnk"; $i++ }
        Move-Item -LiteralPath $f.FullName -Destination $to
        return @{ Action = 'moved'; Path = $to; From = $f.FullName }
    }

    $path = Join-Path $dir "$name.lnk"
    $i = 2
    while (Test-Path -LiteralPath $path) { $path = Join-Path $dir "$name ($i).lnk"; $i++ }
    $sc = (Get-Wsh).CreateShortcut($path)
    $sc.TargetPath = $Option.Target
    $sc.Arguments = $Option.Arguments
    $sc.Description = $Option.Description
    if ($Option.Icon) { $sc.IconLocation = [Environment]::ExpandEnvironmentVariables($Option.Icon) }
    $sc.Save()
    return @{ Action = 'created'; Path = $path }
}

function Invoke-Scan {
    $App.Classic = Test-ClassicMenu
    $items = [System.Collections.Generic.List[object]]::new()
    $blocked = Get-BlockedClsids

    $bases = [ordered]@{}
    foreach ($b in $BaseKeys.Keys) { $bases[$b] = $BaseKeys[$b] }
    $ft = Get-FileTypeBases $App.Ext
    foreach ($b in $ft.Keys) { if (-not $bases.Contains($b)) { $bases[$b] = @{ Label = $ft[$b]; Locs = @('filetypes') } } }

    $handlers = [ordered]@{}
    foreach ($b in $bases.Keys) {
        foreach ($hive in 'HKCU', 'HKLM') {
            Read-Verbs $hive $b $bases[$b] $items
            Read-Handlers $hive $b $bases[$b] $handlers
        }
    }

    foreach ($h in $handlers.Values) {
        $bl = if ($blocked.ContainsKey($h.Clsid)) { $blocked[$h.Clsid] } else { @{} }
        $h.LocIds = $h.LocIdList.ToArray()
        $h.LocLabel = $h.LabelList -join ', '
        $h.Paths = $h.PathList.ToArray()
        $h.SubPath = $h.PathList[0]
        $h.DashPaths = $h.DashList.ToArray()
        $h.BlockedNames = $bl
        $h.Enabled = ($bl.Count -eq 0) -and ($h.DashList.Count -eq 0)
        foreach ($k in 'LocIdList', 'LabelList', 'PathList', 'DashList') { $h.Remove($k) }
        $items.Add((Complete-Entry $h))
    }

    $ext = '.' + $App.Ext.Trim().TrimStart('.').ToLowerInvariant()
    foreach ($r in (Get-PackagedRecords)) {
        $locs = [System.Collections.Generic.List[string]]::new()
        $labels = [System.Collections.Generic.List[string]]::new()
        $exts = [System.Collections.Generic.List[string]]::new()
        foreach ($t in $r.Types) {
            switch ($t) {
                '*'                    { $locs.Add('files'); $labels.Add('Files') }
                'Directory'            { $locs.Add('folders'); $labels.Add('Folders') }
                'Directory\Background' { $locs.Add('background'); $locs.Add('desktop'); $labels.Add('Background') }
                'Drive'                { $locs.Add('drives'); $labels.Add('Drives') }
                default                { if ($t.StartsWith('.')) { $exts.Add($t.ToLowerInvariant()) } }
            }
        }
        if ($exts.Count -gt 0) {
            $labels.Add($(if ($exts.Count -le 3) { $exts -join ', ' } else { "$($exts.Count) file types" }))
            if ($exts.Contains($ext)) { $locs.Add('filetypes') }
        }
        $bl = if ($blocked.ContainsKey($r.Clsid)) { $blocked[$r.Clsid] } else { @{} }
        $verb = Format-Identifier $r.VerbId
        $items.Add((Complete-Entry @{
            Id = "pkg|$($r.Clsid)"; Kind = 'Modern'; Name = $r.App; Sub = $verb; KeyName = $r.VerbId; Hive = 'Package'
            Clsid = $r.Clsid; Package = $r.Package; IconSpec = $r.Logo; LocIds = $locs.ToArray()
            LocLabel = (($labels | Select-Object -Unique) -join ', '); BlockedNames = $bl; Enabled = $bl.Count -eq 0
        }))
    }

    Read-ShellNew $items
    Read-SendTo $items
    $App.Items = $items
}

# ==============================================================================
# ACTIONS (no UI)
# ==============================================================================
function Get-RequiredHive($Item, [bool]$Enable) {
    if ($Item.Kind -eq 'Command' -or $Item.Kind -eq 'New') { return $Item.Hive }
    if ($Item.Kind -eq 'SendTo') { return 'HKCU' }
    if ($Enable) {
        if ($Item.BlockedNames.ContainsKey('HKLM')) { return 'HKLM' }
        if ($Item.DashPaths.Count -gt 0) { return $Item.Hive }
    }
    return 'HKCU'
}

function Set-EntryEnabled($Item, [bool]$Enable) {
    if ($Item.Kind -eq 'Command') {
        $k = (Get-HiveRoot $Item.Hive).OpenSubKey($Item.SubPath, $true)
        if (-not $k) { throw "Registry key no longer exists: $($Item.SubPath)" }
        try {
            if ($Enable) {
                $k.DeleteValue('LegacyDisable', $false)
                $k.DeleteValue('ProgrammaticAccessOnly', $false)
            } else {
                $k.SetValue('LegacyDisable', '')
            }
        } finally { $k.Close() }
        return
    }
    if ($Item.Kind -eq 'New') {
        # Windows ignores a ShellNew key under any other name, so renaming it is a reversible off switch.
        Rename-RegKey $Item.Hive $Item.SubPath $(if ($Enable) { 'ShellNew' } else { '_ShellNew' })
        return
    }
    if ($Item.Kind -eq 'SendTo') {
        # Send To skips hidden files (and hidden submenu folders).
        $fi = Get-Item -LiteralPath $Item.FilePath -Force -ErrorAction SilentlyContinue
        if (-not $fi) { throw "File no longer exists: $($Item.FilePath)" }
        $hidden = [int][IO.FileAttributes]::Hidden
        $fi.Attributes = [IO.FileAttributes]$(if ($Enable) { [int]$fi.Attributes -band -bnot $hidden } else { [int]$fi.Attributes -bor $hidden })
        return
    }

    if ($Enable) {
        foreach ($hive in @($Item.BlockedNames.Keys)) {
            $k = (Get-HiveRoot $hive).OpenSubKey($BlockedPath, $true)
            if ($k) { try { $k.DeleteValue($Item.BlockedNames[$hive], $false) } finally { $k.Close() } }
        }
        foreach ($p in $Item.DashPaths) {
            $k = (Get-HiveRoot $Item.Hive).OpenSubKey($p, $true)
            if ($k) { try { $k.SetValue('', ([string]$k.GetValue('')).TrimStart('-')) } finally { $k.Close() } }
        }
    } else {
        $k = [Microsoft.Win32.Registry]::CurrentUser.CreateSubKey($BlockedPath)
        try { $k.SetValue($Item.Clsid, $Item.Name) } finally { $k.Close() }
    }
}

function Backup-RegKey([string]$Hive, [string]$SubPath, [string]$Label) {
    if (-not (Test-Path -LiteralPath $App.BackupDir)) { New-Item -ItemType Directory -Path $App.BackupDir -Force | Out-Null }
    $safe = $Label -replace '[^\w.-]', '_'
    $stamp = Get-Date -Format 'yyyyMMdd_HHmmss'
    $file = Join-Path $App.BackupDir "$($stamp)_$safe.reg"
    $i = 2
    while (Test-Path -LiteralPath $file) { $file = Join-Path $App.BackupDir "$($stamp)_$($safe)_$i.reg"; $i++ }
    & reg.exe export "$Hive\$SubPath" $file /y *> $null
    if ($LASTEXITCODE -eq 0 -and (Test-Path -LiteralPath $file)) { return $file }
    return $null
}

# Exports several keys into one .reg file. $Keys is a list of "HIVE\SubPath" strings; missing keys are skipped.
function Export-RegKeys([string[]]$Keys, [string]$File) {
    $sb = [Text.StringBuilder]::new()
    [void]$sb.AppendLine('Windows Registry Editor Version 5.00')
    $count = 0
    foreach ($key in $Keys) {
        $p = Split-RegPath $key
        $k = (Get-HiveRoot $p.Hive).OpenSubKey($p.SubPath)
        if (-not $k) { continue }
        $k.Close()
        $tmp = [IO.Path]::GetTempFileName()
        & reg.exe export "$($p.Hive)\$($p.SubPath)" $tmp /y *> $null
        if ($LASTEXITCODE -eq 0) {
            $t = [IO.File]::ReadAllText($tmp)
            [void]$sb.Append($t.Substring($t.IndexOf("`n") + 1))
            $count++
        }
        Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue
    }
    [IO.File]::WriteAllText($File, $sb.ToString(), [Text.Encoding]::Unicode)
    return $count
}

function Export-FullBackup {
    if (-not (Test-Path -LiteralPath $App.BackupDir)) { New-Item -ItemType Directory -Path $App.BackupDir -Force | Out-Null }
    $file = Join-Path $App.BackupDir ('{0}_full_context_menu.reg' -f (Get-Date -Format 'yyyyMMdd_HHmmss'))
    $paths = @(foreach ($b in $BaseKeys.Keys) { "Software\Classes\$b\shell"; "Software\Classes\$b\shellex\ContextMenuHandlers" }) + $BlockedPath
    $keys = foreach ($hive in 'HKCU', 'HKLM') { foreach ($p in $paths) { "$hive\$p" } }
    [void](Export-RegKeys $keys $file)
    return $file
}

# Your own setup, for moving to another PC: per-user commands and submenus, the per-user Blocked list
# and the classic-menu switch. Machine-wide entries belong to installed programs and are left out.
function Export-Setup([string]$File) {
    $keys = @(foreach ($b in $BaseKeys.Keys) { "HKCU\Software\Classes\$b\shell" }) + "HKCU\$BlockedPath" + "HKCU\$ClassicKey"
    return Export-RegKeys $keys $File
}

function Split-RegPath([string]$Path) {
    $i = $Path.IndexOf('\')
    if ($i -lt 0) { return $null }
    $hive = switch ($Path.Substring(0, $i)) { 'HKEY_CURRENT_USER' { 'HKCU' } 'HKCU' { 'HKCU' } 'HKEY_LOCAL_MACHINE' { 'HKLM' } 'HKLM' { 'HKLM' } default { $null } }
    if (-not $hive) { return $null }
    return @{ Hive = $hive; SubPath = $Path.Substring($i + 1) }
}

function Remove-RegTree([string]$Hive, [string]$SubPath) {
    $i = $SubPath.LastIndexOf('\')
    $parent = (Get-HiveRoot $Hive).OpenSubKey($SubPath.Substring(0, $i), $true)
    if ($parent) { try { $parent.DeleteSubKeyTree($SubPath.Substring($i + 1), $false) } finally { $parent.Close() } }
}

# Deletes a command (with anything inside it) or a broken shell-extension registration.
# Every key is backed up before anything is removed. Returns the backup files.
function Remove-MenuEntry($Item) {
    if (-not $Item.CanDelete) { throw 'Only commands and broken extensions can be deleted. Turn other extensions off instead.' }
    if ($Item.Kind -eq 'SendTo') {
        # Send To items are files or submenu folders: move them into Backups\SendTo\<stamp>-<n>\<path inside
        # Send To>, keeping the submenu folder, so a restore puts them back exactly where they were.
        $root = Join-Path $App.BackupDir 'SendTo'
        $stamp = Get-Date -Format 'yyyyMMdd_HHmmss'
        $n = 1
        while (Test-Path -LiteralPath (Join-Path $root "$stamp-$n")) { $n++ }
        $box = Join-Path $root "$stamp-$n"
        $dest = Join-Path $box $Item.KeyName
        New-Item -ItemType Directory -Path (Split-Path -Parent $dest) -Force | Out-Null
        Move-Item -LiteralPath $Item.FilePath -Destination $dest -Force
        return , @($box)
    }
    $backups = @()
    foreach ($p in $Item.Paths) {
        $b = Backup-RegKey $Item.Hive $p "deleted_$($p.Split('\')[-1])"
        if (-not $b) { throw 'Could not write a backup, so nothing was deleted.' }
        $backups += $b
    }
    foreach ($p in $Item.Paths) { Remove-RegTree $Item.Hive $p }
    return , $backups
}

function Get-BackupInfo([IO.FileInfo]$File) {
    $text = try { [IO.File]::ReadAllText($File.FullName) } catch { '' }
    $roots = [System.Collections.Generic.List[string]]::new()
    foreach ($m in [regex]::Matches($text, '(?m)^\[(?!-)([^\]\r\n]+)\]')) {
        $k = $m.Groups[1].Value
        $covered = $false
        foreach ($r in $roots) { if ($k -eq $r -or $k.StartsWith("$r\", [StringComparison]::OrdinalIgnoreCase)) { $covered = $true; break } }
        if (-not $covered) { $roots.Add($k) }
    }

    $label = $File.BaseName
    $when = $File.LastWriteTime
    $m = [regex]::Match($File.BaseName, '^(\d{8}_\d{6})_(.+)$')
    if ($m.Success) {
        $label = $m.Groups[2].Value
        $when = [datetime]::ParseExact($m.Groups[1].Value, 'yyyyMMdd_HHmmss', [Globalization.CultureInfo]::InvariantCulture)
    }
    $action, $name = switch -Regex ($label) {
        '^deleted_(.+)$'        { 'Deleted', $Matches[1]; break }
        '^edited_(.+)$'         { 'Before edit', $Matches[1]; break }
        '^before-restore_(.+)$' { 'Before restore', $Matches[1]; break }
        '^full_context_menu'    { 'Full backup', 'All context menu keys'; break }
        default                 { 'Backup', $label }
    }
    $isFull = $action -eq 'Full backup' -or $roots.Count -gt 1
    if (-not $isFull) {
        $mv = [regex]::Match($text, '(?m)^"MUIVerb"="((?:[^"\\]|\\.)*)"')
        if (-not $mv.Success) { $mv = [regex]::Match($text, '(?m)^@="((?:[^"\\]|\\.)*)"') }
        if ($mv.Success) {
            $friendly = Resolve-MenuText ($mv.Groups[1].Value -replace '\\(.)', '$1')
            if ($friendly) { $name = $friendly }
        }
    }

    $whenText = Format-When $when
    $keyText = if ($roots.Count -eq 1) { $roots[0] -replace '^HKEY_CURRENT_USER', 'HKCU' -replace '^HKEY_LOCAL_MACHINE', 'HKLM' }
               else { "$($roots.Count) registry keys" }

    [pscustomobject]@{
        File = $File.FullName; FileName = $File.Name; Name = $name; Action = $action; When = $when; WhenText = $whenText
        Roots = $roots.ToArray(); KeyText = $keyText; IsFull = $isFull
        NeedsAdmin = [bool]($roots | Where-Object { $_ -like 'HKEY_LOCAL_MACHINE*' })
    }
}

function Format-When([datetime]$When) {
    $today = (Get-Date).Date
    if ($When.Date -eq $today) { return 'Today, ' + $When.ToString('HH:mm') }
    if ($When.Date -eq $today.AddDays(-1)) { return 'Yesterday, ' + $When.ToString('HH:mm') }
    if ($When.Year -eq $today.Year) { return $When.ToString('MMM d, HH:mm') }
    return $When.ToString('MMM d yyyy, HH:mm')
}

function Get-Backups {
    if (-not (Test-Path -LiteralPath $App.BackupDir)) { return @() }
    $list = [System.Collections.Generic.List[object]]::new()
    foreach ($f in Get-ChildItem -LiteralPath $App.BackupDir -Filter *.reg -File) { $list.Add((Get-BackupInfo $f)) }
    $sendDir = Join-Path $App.BackupDir 'SendTo'
    if (Test-Path -LiteralPath $sendDir) {
        foreach ($f in Get-ChildItem -LiteralPath $sendDir -Force) {
            # Current format: folder "<stamp>-<n>" holding the item at its path inside Send To.
            # Older format: file "<stamp>_<name>" that lived at the top of Send To.
            $box = [regex]::Match($f.Name, '^(\d{8}_\d{6})-\d+$')
            $old = [regex]::Match($f.Name, '^(\d{8}_\d{6})_(.+)$')
            if ($box.Success -and $f.PSIsContainer) {
                $inner = Get-ChildItem -LiteralPath $f.FullName -Force | Select-Object -First 1
                if (-not $inner) { continue }
                $rel = $inner.Name
                if ($inner.PSIsContainer) {
                    # One item inside means a single entry of that submenu was deleted; several means the whole submenu.
                    $leaf = @(Get-ChildItem -LiteralPath $inner.FullName -Force | Where-Object Name -ine 'desktop.ini')
                    if ($leaf.Count -eq 1) { $rel = "$($inner.Name)\$($leaf[0].Name)" }
                }
                $when = [datetime]::ParseExact($box.Groups[1].Value, 'yyyyMMdd_HHmmss', [Globalization.CultureInfo]::InvariantCulture)
                $display = ([IO.Path]::GetFileNameWithoutExtension($rel.Split('\')[-1]))
                if ($rel.Contains('\')) { $display = "$($rel.Split('\')[0]) > $display" }
                $list.Add([pscustomobject]@{
                    File = $f.FullName; FileName = $f.Name; Name = $display; Action = 'Deleted'
                    When = $when; WhenText = Format-When $when; Roots = @(); KeyText = "Send to: $rel"; IsFull = $false; NeedsAdmin = $false
                })
            } elseif (-not $f.PSIsContainer) {
                $orig = if ($old.Success) { $old.Groups[2].Value } else { $f.Name }
                $when = if ($old.Success) { [datetime]::ParseExact($old.Groups[1].Value, 'yyyyMMdd_HHmmss', [Globalization.CultureInfo]::InvariantCulture) } else { $f.LastWriteTime }
                $list.Add([pscustomobject]@{
                    File = $f.FullName; FileName = $f.Name; Name = [IO.Path]::GetFileNameWithoutExtension($orig); Action = 'Deleted'
                    When = $when; WhenText = Format-When $when; Roots = @(); KeyText = "Send to: $orig"; IsFull = $false; NeedsAdmin = $false
                })
            }
        }
    }
    return @($list | Sort-Object When -Descending)
}

# Replace mode (default) deletes each key in the file first so the result matches the backup exactly;
# merge mode only adds what the file contains. The current state is backed up before anything is removed,
# and put back if the import fails.
function Restore-BackupFile([string]$File, [switch]$Merge) {
    if (Test-Path -LiteralPath $File -PathType Container) {
        # A Send To item moved aside by Remove-MenuEntry: merge the box's contents back into Send To,
        # which also recreates a submenu folder if it was removed.
        foreach ($inner in Get-ChildItem -LiteralPath $File -Force) {
            $dest = Join-Path (Get-SendToDir) $inner.Name
            if ($inner.PSIsContainer -and (Test-Path -LiteralPath $dest)) {
                foreach ($c in Get-ChildItem -LiteralPath $inner.FullName -Force) { Copy-Item -LiteralPath $c.FullName -Destination (Join-Path $dest $c.Name) -Recurse -Force }
            } else {
                Copy-Item -LiteralPath $inner.FullName -Destination $dest -Recurse -Force
            }
        }
        return , @()
    }
    if ([IO.Path]::GetExtension($File) -ne '.reg') {
        # Older Send To backups: a single file "<stamp>_<name>" from the top of Send To.
        $orig = [IO.Path]::GetFileName($File) -replace '^\d{8}_\d{6}_', ''
        Copy-Item -LiteralPath $File -Destination (Join-Path (Get-SendToDir) $orig) -Force
        return , @()
    }
    $info = Get-BackupInfo ([IO.FileInfo]::new($File))
    $pre = @()
    if (-not $Merge) {
        foreach ($r in $info.Roots) {
            $p = Split-RegPath $r
            if (-not $p) { continue }
            $k = (Get-HiveRoot $p.Hive).OpenSubKey($p.SubPath)
            if (-not $k) { continue }
            $k.Close()
            $b = Backup-RegKey $p.Hive $p.SubPath "before-restore_$($p.SubPath.Split('\')[-1])"
            if (-not $b) { throw 'Could not back up the current version, so nothing was restored.' }
            $pre += $b
            Remove-RegTree $p.Hive $p.SubPath
        }
    }
    & reg.exe import $File *> $null
    if ($LASTEXITCODE -ne 0) {
        foreach ($b in $pre) { & reg.exe import $b *> $null }
        throw "Windows could not import $([IO.Path]::GetFileName($File)). Nothing was changed."
    }
    return , $pre
}

# Creates or updates a static verb or submenu. $ShellPath is the "...\shell" key it lives in
# (a submenu's own "shell" key for commands inside it). Returns the entry Id of the saved item.
function Save-MenuCommand {
    param($Existing, [string]$Name, [string]$Command, [string]$Icon, [string]$Hive, [string]$ShellPath,
          [bool]$Extended, [bool]$Shield, [string]$Position, [bool]$IsSubmenu)

    $root = Get-HiveRoot $Hive
    $moving = $Existing -and ($Existing.Hive -ne $Hive -or $Existing.ShellPath -ne $ShellPath)

    $App.LastBackup = $null
    if ($Existing) {
        $App.LastBackup = Backup-RegKey $Existing.Hive $Existing.SubPath "edited_$($Existing.KeyName)"
        if (-not $App.LastBackup) { throw 'Could not back up the current version, so nothing was changed.' }
    }

    if ($Existing -and -not $moving) {
        $keyName = $Existing.KeyName
    } else {
        $stem = if ($Existing) { $Existing.KeyName } else { ConvertTo-KeyName $Name }
        $keyName = $stem
        $taken = @()
        $sk = $root.OpenSubKey($ShellPath)
        if ($sk) { $taken = $sk.GetSubKeyNames(); $sk.Close() }
        $i = 2
        while ($taken -contains $keyName) { $keyName = "$stem$i"; $i++ }
    }

    $k = $root.CreateSubKey("$ShellPath\$keyName")
    try {
        if ($moving) {
            $src = (Get-HiveRoot $Existing.Hive).OpenSubKey($Existing.SubPath)
            if ($src) { try { Copy-RegTree $src $k } finally { $src.Close() } }
        }

        if (-not $Existing -or $Name -ne $Existing.Name) {
            # A single & is a keyboard accelerator in menus; double it so the name shows as typed.
            $menuText = $Name.Replace('&', '&&')
            $k.SetValue('MUIVerb', $menuText)
            if (-not $Existing) { $k.SetValue('', $menuText) }
        }

        if (-not $Existing -or $Icon -ne $Existing.IconValue) {
            if ($Icon) { Set-RegString $k 'Icon' $Icon } else { $k.DeleteValue('Icon', $false) }
        }

        if ($IsSubmenu) {
            # SubCommands="" plus a nested "shell" key is the static cascading-menu format.
            if (-not $Existing) {
                $k.SetValue('SubCommands', '')
                $k.CreateSubKey('shell').Close()
            }
        } elseif (-not $Existing -or $Command -ne $Existing.Command) {
            $ck = $k.CreateSubKey('command')
            try {
                if ($Command) {
                    Set-RegString $ck '' $Command
                    $ck.DeleteValue('DelegateExecute', $false)
                }
            } finally { $ck.Close() }
        }

        if ($Extended) { $k.SetValue('Extended', '') } else { $k.DeleteValue('Extended', $false) }
        if ($Shield) { $k.SetValue('HasLUAShield', '') } else { $k.DeleteValue('HasLUAShield', $false) }
        if ($Position) { $k.SetValue('Position', $Position) } else { $k.DeleteValue('Position', $false) }
    } finally { $k.Close() }

    if ($moving) { Remove-RegTree $Existing.Hive $Existing.SubPath }
    return "cmd|$Hive|$ShellPath\$keyName"
}

function Test-ClassicMenu {
    $k = [Microsoft.Win32.Registry]::CurrentUser.OpenSubKey("$ClassicKey\InprocServer32")
    if ($k) { $k.Close(); return $true }
    return $false
}

function Set-ClassicMenu([bool]$On) {
    if ($On) {
        $k = [Microsoft.Win32.Registry]::CurrentUser.CreateSubKey("$ClassicKey\InprocServer32")
        try { $k.SetValue('', '') } finally { $k.Close() }
    } else {
        [Microsoft.Win32.Registry]::CurrentUser.DeleteSubKeyTree($ClassicKey, $false)
    }
}

# ------------------------------------------------------------------------------
# Presets. Every key we write carries CMEPreset=<id> so removal never touches keys we didn't create.
# ------------------------------------------------------------------------------
function Find-VSCode {
    $candidates = @("$env:LOCALAPPDATA\Programs\Microsoft VS Code\Code.exe", "$env:ProgramFiles\Microsoft VS Code\Code.exe")
    $cmd = Get-Command code.cmd -CommandType Application -ErrorAction Ignore | Select-Object -First 1
    if ($cmd) { $candidates += Join-Path (Split-Path (Split-Path $cmd.Source)) 'Code.exe' }
    foreach ($c in $candidates) { if ($c -and [IO.File]::Exists($c)) { return $c } }
    return $null
}

function Find-Pwsh {
    foreach ($c in @("$env:ProgramFiles\PowerShell\7\pwsh.exe", "$env:ProgramFiles\PowerShell\7-preview\pwsh.exe")) {
        if ([IO.File]::Exists($c)) { return $c }
    }
    # Store installs live in a versioned WindowsApps folder that changes on every update; the alias does not.
    $alias = "$env:LOCALAPPDATA\Microsoft\WindowsApps\pwsh.exe"
    if (Test-Path -LiteralPath $alias) { return $alias }
    $cmd = Get-Command pwsh.exe -CommandType Application -ErrorAction Ignore | Select-Object -First 1
    if ($cmd) { return $cmd.Source }
    return $null
}

function Get-PresetSpec([string]$Id) {
    switch ($Id) {
        'vscode' {
            $exe = Find-VSCode
            if (-not $exe) { return $null }
            return @(
                @{ Base = '*';                    Key = 'OpenWithCode'; Name = 'Open with Code'; Icon = $exe; Cmd = "`"$exe`" `"%1`"" }
                @{ Base = 'Directory';            Key = 'OpenWithCode'; Name = 'Open with Code'; Icon = $exe; Cmd = "`"$exe`" `"%V`"" }
                @{ Base = 'Directory\Background'; Key = 'OpenWithCode'; Name = 'Open with Code'; Icon = $exe; Cmd = "`"$exe`" `"%V`"" }
            )
        }
        'pwsh' {
            $exe = Find-Pwsh
            if (-not $exe) { return $null }
            # "%V\." avoids the trailing-backslash-escapes-the-quote problem on drive roots (C:\)
            return @(
                @{ Base = 'Directory';            Key = 'OpenPwshHere'; Name = 'Open PowerShell 7 here'; Icon = $exe; Cmd = "`"$exe`" -NoExit -WorkingDirectory `"%V\.`"" }
                @{ Base = 'Directory\Background'; Key = 'OpenPwshHere'; Name = 'Open PowerShell 7 here'; Icon = $exe; Cmd = "`"$exe`" -NoExit -WorkingDirectory `"%V\.`"" }
            )
        }
        'takeown' {
            # A verb named "runas" is what makes Explorer elevate it.
            return @(
                @{ Base = '*'; Key = 'runas'; Name = 'Take ownership'; Icon = 'imageres.dll,-78'; Isolated = $true
                   Extra = @{ HasLUAShield = ''; NoWorkingDirectory = '' }
                   Cmd = 'cmd.exe /c takeown /f "%1" && icacls "%1" /grant *S-1-3-4:F /c /l' }
                @{ Base = 'Directory'; Key = 'runas'; Name = 'Take ownership'; Icon = 'imageres.dll,-78'; Isolated = $true
                   Extra = @{ HasLUAShield = ''; NoWorkingDirectory = '' }
                   Cmd = 'cmd.exe /c takeown /f "%1" /r /d y && icacls "%1" /grant *S-1-3-4:F /t /c /l /q' }
            )
        }
        'copypath' {
            return @(
                @{ Base = '*';         Key = 'CopyFullPath'; Name = 'Copy full path'; Icon = 'imageres.dll,-5302'; Cmd = 'cmd.exe /c <nul set /p ="%1"| clip' }
                @{ Base = 'Directory'; Key = 'CopyFullPath'; Name = 'Copy full path'; Icon = 'imageres.dll,-5302'; Cmd = 'cmd.exe /c <nul set /p ="%1"| clip' }
            )
        }
        'sha256' {
            $cmd = 'powershell.exe -NoProfile -NoExit -Command "$p=\"%1\"; $s=[IO.File]::OpenRead($p); $h=[BitConverter]::ToString([Security.Cryptography.SHA256]::Create().ComputeHash($s)).Replace(\"-\",\"\"); $s.Close(); Write-Host \"`n  $p`n\"; Write-Host \"  SHA256  $h`n\" -ForegroundColor Green"'
            return @(@{ Base = '*'; Key = 'Sha256Hash'; Name = 'Show SHA-256 hash'; Icon = 'powershell.exe'; Cmd = $cmd })
        }
        'godmode' {
            return @(@{ Base = 'DesktopBackground'; Key = 'GodMode'; Name = 'God Mode'; Icon = 'control.exe'; Cmd = 'explorer.exe shell:::{ED7BA470-8E54-465E-825C-99712043E01C}' })
        }
    }
    return $null
}

function Test-PresetInstalled([string]$Id, $Spec) {
    if (-not $Spec) { return $false }
    foreach ($s in $Spec) {
        $k = [Microsoft.Win32.Registry]::CurrentUser.OpenSubKey("Software\Classes\$($s.Base)\shell\$($s.Key)")
        if (-not $k) { return $false }
        $mark = [string]$k.GetValue('CMEPreset')
        $k.Close()
        if ($mark -ne $Id) { return $false }
    }
    return $true
}

function Install-Preset([string]$Id) {
    $spec = Get-PresetSpec $Id
    if (-not $spec) { throw 'The program this shortcut needs was not found.' }
    foreach ($s in $spec) {
        $path = "Software\Classes\$($s.Base)\shell\$($s.Key)"
        $existing = [Microsoft.Win32.Registry]::CurrentUser.OpenSubKey($path)
        if ($existing) {
            $mark = [string]$existing.GetValue('CMEPreset')
            $existing.Close()
            if ($mark -ne $Id) { throw "A different '$($s.Key)' entry already exists for $($s.Base). Remove it first." }
        }
        $k = [Microsoft.Win32.Registry]::CurrentUser.CreateSubKey($path)
        try {
            $k.SetValue('', $s.Name)
            $k.SetValue('MUIVerb', $s.Name)
            $k.SetValue('Icon', $s.Icon)
            $k.SetValue('CMEPreset', $Id)
            if ($s.Extra) { foreach ($e in $s.Extra.Keys) { $k.SetValue($e, $s.Extra[$e]) } }
            $ck = $k.CreateSubKey('command')
            try {
                $ck.SetValue('', $s.Cmd)
                if ($s.Isolated) { $ck.SetValue('IsolatedCommand', $s.Cmd) }
            } finally { $ck.Close() }
        } finally { $k.Close() }
    }
}

function Uninstall-Preset([string]$Id) {
    foreach ($base in $BaseKeys.Keys) {
        $shell = [Microsoft.Win32.Registry]::CurrentUser.OpenSubKey("Software\Classes\$base\shell", $true)
        if (-not $shell) { continue }
        try {
            foreach ($n in $shell.GetSubKeyNames()) {
                $k = $shell.OpenSubKey($n)
                $mark = if ($k) { [string]$k.GetValue('CMEPreset') } else { '' }
                if ($k) { $k.Close() }
                if ($mark -eq $Id) { $shell.DeleteSubKeyTree($n, $false) }
            }
        } finally { $shell.Close() }
    }
}

# ------------------------------------------------------------------------------
# Tweaks (config\tweaks.json): each tweak has registry entries
# ({ Path, Name, Type, Value, OriginalValue }) and/or InvokeScript / UndoScript lines.
# Applying writes Value, undoing writes OriginalValue; "<RemoveEntry>" deletes the value.
# Also: DetectScript (is it applied?), UnavailableScript (returns a reason
# when it can't apply on this PC) and RestartExplorer (changes show after an Explorer restart).
# ------------------------------------------------------------------------------
function Get-TweakDefinitions {
    $list = [System.Collections.Generic.List[object]]::new()
    if (-not $Config['tweaks']) { return }
    foreach ($p in $Config['tweaks'].PSObject.Properties) {
        $t = $p.Value
        $list.Add([pscustomobject]@{
            Id = $p.Name; Content = [string]$t.Content; Description = [string]$t.Description
            Category = [string]$t.category; IsToggle = [string]$t.Type -eq 'Toggle'; RestartExplorer = [bool]$t.RestartExplorer
            Registry = @($t.registry | Where-Object { $_ }); InvokeScript = @($t.InvokeScript | Where-Object { $_ })
            UndoScript = @($t.UndoScript | Where-Object { $_ }); DetectScript = [string]$t.DetectScript
            UnavailableScript = [string]$t.UnavailableScript
        })
    }
    return $list.ToArray()   # plain array: callers pipe it into Where-Object
}

function Get-TweakPresets {
    $h = [ordered]@{}
    if ($Config['preset']) { foreach ($p in $Config['preset'].PSObject.Properties) { $h[$p.Name] = @($p.Value) } }
    return $h
}

# "HKCU:\Software\..." -> @{ Hive; SubPath }
function Split-TweakPath([string]$Path) {
    $m = [regex]::Match($Path, '^(HKCU|HKLM|HKEY_CURRENT_USER|HKEY_LOCAL_MACHINE):?\\(.+)$')
    if (-not $m.Success) { throw "Unsupported registry path in tweak: $Path" }
    $hive = if ($m.Groups[1].Value -like 'HKLM*' -or $m.Groups[1].Value -like 'HKEY_LOCAL*') { 'HKLM' } else { 'HKCU' }
    return @{ Hive = $hive; SubPath = $m.Groups[2].Value }
}

function Get-TweakValueName([string]$Name) { if ($Name -eq '(default)') { return '' } return $Name }

function Set-TweakRegistryValue($Entry, [string]$Value) {
    $p = Split-TweakPath $Entry.Path
    $name = Get-TweakValueName $Entry.Name
    $root = Get-HiveRoot $p.Hive
    if ($Value -eq '<RemoveEntry>') {
        $k = $root.OpenSubKey($p.SubPath, $true)
        if ($k) { try { $k.DeleteValue($name, $false) } finally { $k.Close() } }
        return
    }
    $k = $root.CreateSubKey($p.SubPath)
    try {
        switch ([string]$Entry.Type) {
            'DWord'        { $k.SetValue($name, [int]$Value, [Microsoft.Win32.RegistryValueKind]::DWord) }
            'QWord'        { $k.SetValue($name, [long]$Value, [Microsoft.Win32.RegistryValueKind]::QWord) }
            'ExpandString' { $k.SetValue($name, $Value, [Microsoft.Win32.RegistryValueKind]::ExpandString) }
            default        { $k.SetValue($name, $Value, [Microsoft.Win32.RegistryValueKind]::String) }
        }
    } finally { $k.Close() }
}

function Test-TweakRegistryValue($Entry) {
    $p = Split-TweakPath $Entry.Path
    $k = (Get-HiveRoot $p.Hive).OpenSubKey($p.SubPath)
    $name = Get-TweakValueName $Entry.Name
    $present = $k -and ($k.GetValueNames() -contains $name)
    try {
        if ([string]$Entry.Value -eq '<RemoveEntry>') { return -not $present }
        if (-not $present) { return $false }
        return [string]$k.GetValue($name, $null, 'DoNotExpandEnvironmentNames') -eq [string]$Entry.Value
    } finally { if ($k) { $k.Close() } }
}

function Invoke-TweakScript([string]$Code) {
    if (-not $Code) { return $null }
    return & ([scriptblock]::Create($Code))
}

# @{ Applied; Available; Note } for one tweak definition.
function Get-TweakState($Tweak) {
    $reason = [string](Invoke-TweakScript $Tweak.UnavailableScript)
    $applied = $false
    try {
        if ($Tweak.DetectScript) { $applied = [bool](Invoke-TweakScript $Tweak.DetectScript) }
        elseif ($Tweak.Registry.Count) { $applied = -not ($Tweak.Registry | Where-Object { -not (Test-TweakRegistryValue $_) }) }
    } catch { $applied = $false }
    return @{ Applied = $applied; Available = -not $reason; Note = $reason }
}

function Test-TweakNeedsAdmin($Tweak) {
    return [bool]($Tweak.Registry | Where-Object { (Split-TweakPath $_.Path).Hive -eq 'HKLM' })
}

# Applies (or with -Undo, reverts) one tweak.
function Invoke-Tweak($Tweak, [switch]$Undo) {
    foreach ($e in $Tweak.Registry) {
        Set-TweakRegistryValue $e $(if ($Undo) { [string]$e.OriginalValue } else { [string]$e.Value })
    }
    foreach ($s in $(if ($Undo) { $Tweak.UndoScript } else { $Tweak.InvokeScript })) { [void](Invoke-TweakScript $s) }
}

