# ==============================================================================
# UI HELPERS
# ==============================================================================
# Embedded brand image (see Compile.ps1 / tools\Build-Assets.ps1) as a frozen WPF image, or $null.
function Get-AssetImage([string]$Name) {
    if (-not $Assets -or -not $Assets[$Name]) { return $null }
    try {
        $ms = [IO.MemoryStream]::new([Convert]::FromBase64String($Assets[$Name]))
        $img = if ($Name -like '*.ico') {
            [System.Windows.Media.Imaging.BitmapFrame]::Create($ms, [System.Windows.Media.Imaging.BitmapCreateOptions]::None, [System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad)
        } else {
            $bi = [System.Windows.Media.Imaging.BitmapImage]::new()
            $bi.BeginInit(); $bi.StreamSource = $ms; $bi.CacheOption = [System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad; $bi.EndInit()
            $bi
        }
        $img.Freeze()
        return $img
    } catch { return $null }
}

function New-Window([string]$Xaml) {
    $x = [xml]($Xaml.Replace('<!--RES-->', $ResXaml))
    $w = [Windows.Markup.XamlReader]::Load([System.Xml.XmlNodeReader]::new($x))
    if (-not $App.Icon) { $App.Icon = Get-AssetImage 'app-icon.ico' }
    if ($App.Icon) { $w.Icon = $App.Icon }
    $w.Add_SourceInitialized({
        param($sender)
        try { [CME.Native]::DarkTitleBar([System.Windows.Interop.WindowInteropHelper]::new($sender).Handle, 0x1F1C1B) } catch {}
    })
    return $w
}

function Show-Message {
    param([string]$Title, [string]$Text, [string[]]$Buttons = @('OK'), [string]$Primary = '', [switch]$Danger)
    $w = New-Window $MessageXaml
    if ($Window -and $Window.IsLoaded) { $w.Owner = $Window }
    $w.Title = $Title
    $w.FindName('MsgTitle').Text = $Title
    $w.FindName('MsgText').Text = $Text
    $panel = $w.FindName('MsgButtons')
    $res = @{ Value = $null }
    foreach ($label in $Buttons) {
        $b = [System.Windows.Controls.Button]::new()
        $b.Content = $label
        $b.Tag = $label
        $b.MinWidth = 86
        $b.Margin = [System.Windows.Thickness]::new(8, 0, 0, 0)
        $styleKey = if ($label -eq $Primary) { if ($Danger) { 'BtnDanger' } else { 'BtnPrimary' } } else { 'Btn' }
        $b.Style = $w.FindResource($styleKey)
        if ($label -eq $Primary) { $b.IsDefault = $true }
        $b.Add_Click({ param($s) $res.Value = $s.Tag; $w.Close() })
        [void]$panel.Children.Add($b)
    }
    [void]$w.ShowDialog()
    return $res.Value
}

# A dialog with a switch per choice (all on by default), plus an optional extra switch shown above them.
# Returns @{ Selected = labels; Extra = bool }, or $null if cancelled.
function Show-Choices([string]$Title, [string]$Text, [string[]]$Choices, [string]$Action, [string]$ExtraLabel) {
    $w = New-Window $MessageXaml
    if ($Window -and $Window.IsLoaded) { $w.Owner = $Window }
    $w.Title = $Title
    $w.FindName('MsgTitle').Text = $Title
    $msg = $w.FindName('MsgText')
    $msg.Text = $Text
    $host_ = $msg.Parent
    $extra = $null
    if ($ExtraLabel) {
        $box = [System.Windows.Controls.Border]::new()
        $box.Background = $w.FindResource('Surface')
        $box.CornerRadius = [System.Windows.CornerRadius]::new(8)
        $box.Padding = [System.Windows.Thickness]::new(12, 10, 12, 10)
        $box.Margin = [System.Windows.Thickness]::new(0, 14, 0, 0)
        $extra = [System.Windows.Controls.CheckBox]::new()
        $extra.Style = $w.FindResource('Switch')
        $extra.Content = $ExtraLabel
        $extra.IsChecked = $true
        $box.Child = $extra
        [void]$host_.Children.Add($box)
    }
    $list = [System.Windows.Controls.StackPanel]::new()
    $list.Margin = [System.Windows.Thickness]::new(0, 14, 0, 0)
    $boxes = foreach ($ch in $Choices) {
        $cb = [System.Windows.Controls.CheckBox]::new()
        $cb.Style = $w.FindResource('Switch')
        $cb.Content = $ch
        $cb.IsChecked = $true
        $cb.Margin = [System.Windows.Thickness]::new(0, 0, 0, 10)
        [void]$list.Children.Add($cb)
        $cb
    }
    [void]$host_.Children.Add($list)
    $res = @{ Value = $null }
    $panel = $w.FindName('MsgButtons')
    foreach ($label in 'Cancel', $Action) {
        $b = [System.Windows.Controls.Button]::new()
        $b.Content = $label
        $b.MinWidth = 86
        $b.Margin = [System.Windows.Thickness]::new(8, 0, 0, 0)
        $b.Style = $w.FindResource($(if ($label -eq $Action) { 'BtnPrimary' } else { 'Btn' }))
        if ($label -eq $Action) {
            $b.IsDefault = $true
            $b.Add_Click({
                $res.Value = @{ Selected = @($boxes | Where-Object IsChecked | ForEach-Object { [string]$_.Content }); Extra = [bool]($extra -and $extra.IsChecked) }
                $w.Close()
            })
        } else {
            $b.IsCancel = $true
            $b.Add_Click({ $w.Close() })
        }
        [void]$panel.Children.Add($b)
    }
    [void]$w.ShowDialog()
    return $res.Value
}

function Invoke-AddToSendTo($Item) {
    if (-not $Item) { return }
    $Window.Cursor = [System.Windows.Input.Cursors]::Wait
    try {
        $opts = Get-SendToOptions $Item   # returns its array as one object; @() would nest it
    } catch {
        $Window.Cursor = $null
        [void](Show-Message -Title "Can't add `"$($Item.Name)`" to Send to" -Text $_.Exception.Message)
        return
    }
    $Window.Cursor = $null

    $group = @($opts | ForEach-Object { $_.Group } | Where-Object { $_ } | Select-Object -Unique)
    $grouped = [bool]$group
    $chosen = $opts
    if ($opts.Count -gt 1 -or $group) {
        $answer = Show-Choices -Title "Add `"$($Item.Name)`" to Send to" -Action 'Add' -Choices @($opts | ForEach-Object { $_.Short }) `
            -Text 'Each one becomes its own Send to item that runs the same thing as the right-click menu. Turn off the ones you don''t want.' `
            -ExtraLabel $(if ($group) { "Put them in a `"$($group[0])`" submenu" } else { '' })
        if ($null -eq $answer) { return }
        $chosen = @($opts | Where-Object { $answer.Selected -contains $_.Short })
        $grouped = $answer.Extra
        if (-not $chosen) { return }
    }

    $created = [System.Collections.Generic.List[string]]::new()
    $moves = [System.Collections.Generic.List[object]]::new()
    $existing = 0
    $folder = $null
    try {
        if ($grouped -and $group) {
            $folder = Initialize-SendToFolder $group[0] $chosen[0].GroupIcon
        }
        foreach ($o in $chosen) {
            $r = New-SendToShortcut $o -Grouped:$grouped
            switch ($r.Action) {
                'created' { $created.Add($r.Path) }
                'moved'   { $moves.Add(@{ From = $r.From; To = $r.Path }) }
                default   { $existing++ }
            }
        }
    } catch {
        [void](Show-Message -Title 'Could not add it' -Text $_.Exception.Message)
    }
    if ($created.Count -or $moves.Count) {
        $parts = @()
        if ($created.Count) { $parts += "added $($created.Count)" }
        if ($moves.Count) { $parts += "moved $($moves.Count) existing" }
        $where = if ($folder) { " in Send to > $($group[0])" } else { ' to Send to' }
        $msg = (($parts -join ', ') + $where)
        if ($existing) { $msg += " ($existing already there)" }
        Set-Status "$($msg.Substring(0,1).ToUpper())$($msg.Substring(1)). Right-click a file > Send to to use it."
        # Undo moves things back; a submenu folder created here goes away with what was created in it.
        $deleteFiles = if ($folder -and $folder.Created) { @($folder.Path) } else { $created.ToArray() }
        Set-Undo @{ Type = 'restore'; Files = @(); DeletePaths = @(); Moves = $moves.ToArray(); DeleteFiles = $deleteFiles; Label = 'adding to Send to' }
        Invoke-Refresh -Rescan
    } elseif ($existing) {
        Set-Status 'Already in Send to; nothing to add.'
    }
}

function Set-Status([string]$Text) { $U.TxtStatus.Text = $Text }

function Set-PendingRestart { $U.PendingBar.Visibility = 'Visible' }

function Restart-Elevated {
    $exe = [Diagnostics.Process]::GetCurrentProcess().MainModule.FileName
    $sta = if ($PSVersionTable.PSEdition -eq 'Desktop') { ' -STA' } else { '' }
    if ($App.ScriptPath) {
        $run = "-File `"$($App.ScriptPath)`""
    } elseif ($AppLaunchUrl) {
        # Started with "irm <url> | iex": there's no file to relaunch, so the elevated copy downloads it again.
        $run = '-Command "irm ''' + $AppLaunchUrl.Replace("'", "''''") + ''' | iex"'
    } else {
        [void](Show-Message -Title 'Run it as administrator yourself' -Text 'This copy was started without a file or launch URL, so it can''t restart itself. Open PowerShell as administrator and start it again from there.')
        return
    }
    # conhost --headless keeps the elevated instance from opening a console or terminal window.
    $argLine = "--headless `"$exe`" -NoProfile -ExecutionPolicy Bypass$sta $run"
    try {
        Start-Process -FilePath 'conhost.exe' -ArgumentList $argLine -Verb RunAs -ErrorAction Stop
        $Window.Close()
    } catch {
        Set-Status 'Elevation was cancelled.'
    }
}

# Runs a registry write; turns access-denied into a friendly prompt to restart elevated.
function Invoke-Write([string]$Hive, [scriptblock]$Action) {
    if ($Hive -eq 'HKLM' -and -not $App.IsAdmin) {
        $r = Show-Message -Title 'Administrator rights needed' `
            -Text 'This entry is installed for all users, so changing it needs administrator rights. Restart the editor as administrator?' `
            -Buttons @('Cancel', 'Restart as admin') -Primary 'Restart as admin'
        if ($r -eq 'Restart as admin') { Restart-Elevated }
        return $false
    }
    try {
        & $Action
        return $true
    } catch {
        $msg = $_.Exception.Message
        if ($_.Exception -is [System.Security.SecurityException] -or $_.Exception -is [UnauthorizedAccessException] -or
            $_.Exception.InnerException -is [System.Security.SecurityException] -or $_.Exception.InnerException -is [UnauthorizedAccessException]) {
            $msg = "Windows denied access to that registry key. $msg"
        }
        [void](Show-Message -Title 'Could not apply the change' -Text $msg)
        return $false
    }
}

function Find-VisualChild($Element, [type]$Type) {
    if ($Element -is $Type) { return $Element }
    for ($i = 0; $i -lt [System.Windows.Media.VisualTreeHelper]::GetChildrenCount($Element); $i++) {
        $r = Find-VisualChild ([System.Windows.Media.VisualTreeHelper]::GetChild($Element, $i)) $Type
        if ($r) { return $r }
    }
    return $null
}

function Test-InNav($Item, [string]$Nav) {
    if ($Nav -eq 'all') { return $Item.Kind -eq 'Modern' -or @($Item.LocIds | Where-Object { $_ -notin 'filetypes', 'newmenu', 'sendto' }).Count -gt 0 }
    if ($Nav -eq 'broken') { return $Item.Broken }
    return $Item.LocIds -contains $Nav
}

# The New menu and Send To lists are their own kinds; the Commands/Extensions filter doesn't apply there.
$KindlessNavs = @('newmenu', 'sendto')

function Test-Kind($Item) {
    if ($Item.Kind -eq 'New' -or $Item.Kind -eq 'SendTo') { return $App.Kind -eq 'all' }
    switch ($App.Kind) {
        'cmd' { return $Item.Kind -eq 'Command' }
        'ext' { return $Item.Kind -ne 'Command' }
        default { return $true }
    }
}

$NavText = @{
    all        = @('Everything', 'Every right-click entry Windows knows about')
    files      = @('Files', 'Shown when you right-click any file')
    folders    = @('Folders', 'Shown when you right-click a folder')
    background = @('Folder background', 'Shown when you right-click empty space inside a folder (and on the desktop)')
    desktop    = @('Desktop', 'Shown when you right-click the desktop')
    drives     = @('Drives', 'Shown when you right-click a drive in This PC')
    filetypes  = @('File types', 'Entries that only appear for one extension')
    newmenu    = @('New menu', 'The file types offered under New when you right-click a folder background')
    sendto     = @('Send to', 'Shortcuts in your Send To folder')
    broken     = @('Broken entries', 'Entries that point to a program or DLL that no longer exists')
    backups    = @('Backups', 'Every edit and delete saves the old version here first')
    tweaks     = @('Tweaks', 'Check what you want or pick a preset, then Run tweaks. Undo selected puts the original values back')
}

function Update-View {
    # Broken entries are listed even when they are Windows built-ins: a dead entry is worth seeing either way.
    $everything = @($App.Items)
    $all = @($everything | Where-Object { Test-Kind $_ })
    $base = @($all | Where-Object { $App.ShowBuiltIn -or -not $_.IsBuiltIn })
    $plain = @($everything | Where-Object { $App.ShowBuiltIn -or -not $_.IsBuiltIn })

    foreach ($n in $NavEntries) {
        if ($n.Id -eq 'tweaks' -or $n.Id -eq 'backups') { continue }
        $src = if ($n.Id -eq 'broken') { $all } elseif ($KindlessNavs -contains $n.Id) { $plain } else { $base }
        $n.Count = [string]@($src | Where-Object { Test-InNav $_ $n.Id }).Count
    }

    if ($App.Nav -eq 'tweaks' -or $App.Nav -eq 'backups') { return }

    $src = if ($App.Nav -eq 'broken') { $all } elseif ($KindlessNavs -contains $App.Nav) { $plain } else { $base }
    $inNav = @($src | Where-Object { Test-InNav $_ $App.Nav })
    $q = $App.Search.Trim().ToLowerInvariant()
    $shown = if ($q) { @($inNav | Where-Object { $_.SearchText.Contains($q) }) } else { $inNav }

    $App.View.Clear()
    foreach ($it in ($shown | Sort-Object GroupKey, ChildOrder, Name)) { $App.View.Add($it) }

    $off = @($inNav | Where-Object { -not $_.Enabled }).Count
    $sub = "$($inNav.Count) entries"
    if ($off) { $sub += ", $off turned off" }
    if ($App.Nav -eq 'filetypes') { $sub = "$($NavText.filetypes[1]): $($App.Ext)  /  $sub" } else { $sub = "$($NavText[$App.Nav][1])  /  $sub" }
    $U.TxtSubtitle.Text = $sub

    if ($App.Nav -eq 'broken') {
        $removable = @($inNav | Where-Object CanDelete).Count
        $U.BtnCleanup.Content = "Remove all ($removable)"
        $U.BtnCleanup.IsEnabled = $removable -gt 0
    }

    if ($App.View.Count -eq 0) {
        $U.EmptyState.Visibility = 'Visible'
        if ($q) {
            $U.TxtEmpty.Text = "No matches for `"$($App.Search.Trim())`""
            $U.TxtEmptySub.Text = 'Try a different word, or switch on Windows built-ins.'
        } elseif ($App.Nav -eq 'broken') {
            $U.TxtEmpty.Text = 'No broken entries'
            $U.TxtEmptySub.Text = 'Every entry points to a program or DLL that exists.'
        } else {
            $U.TxtEmpty.Text = 'Nothing here yet'
            $U.TxtEmptySub.Text = 'Add a command with "New command", or switch on Windows built-ins to see the defaults.'
        }
    } else {
        $U.EmptyState.Visibility = 'Collapsed'
    }
}

function Update-Detail {
    $it = $U.ItemList.SelectedItem
    $selected = @($U.ItemList.SelectedItems)
    $U.DetailMulti.Visibility = 'Collapsed'
    if (-not $it) {
        $U.DetailEmpty.Visibility = 'Visible'
        $U.DetailBody.Visibility = 'Collapsed'
        return
    }
    $U.DetailEmpty.Visibility = 'Collapsed'
    if ($selected.Count -gt 1) {
        $U.DetailBody.Visibility = 'Collapsed'
        $U.DetailMulti.Visibility = 'Visible'
        $on = @($selected | Where-Object Enabled).Count
        $U.TxtMultiTitle.Text = "$($selected.Count) entries selected"
        $U.TxtMultiSub.Text = "$on on, $($selected.Count - $on) off. Ctrl+click or Shift+click to change the selection."
        $deletable = @($selected | Where-Object CanDelete).Count
        $U.BtnMultiDelete.Content = if ($deletable -eq $selected.Count) { 'Delete all' } else { "Delete $deletable of $($selected.Count)" }
        $U.BtnMultiDelete.IsEnabled = $deletable -gt 0
        return
    }
    $U.DetailBody.Visibility = 'Visible'

    $U.DetailName.Text = $it.Name
    $U.DetailKind.Text = $it.KindLabel + $(if ($it.IsBuiltIn) { '  /  Windows built-in' } else { '' })
    $U.DetailIcon.Source = $it.IconImage
    $U.DetailGlyph.Data = [System.Windows.Media.Geometry]::Parse($it.Glyph)
    $U.DetailGlyph.Visibility = if ($it.IconImage) { 'Collapsed' } else { 'Visible' }
    $U.DetailSwitch.IsChecked = $it.Enabled
    $U.DetailState.Text = if ($it.Enabled) { 'Shown in the menu' } else { 'Hidden from the menu' }
    $U.DetailState.Foreground = if ($it.Enabled) { $Window.FindResource('Text') } else { $Window.FindResource('Warn') }
    $U.DetailStateSub.Text = switch ($it.Kind) {
        'Command' { if ($it.Submenu) { 'Turning it off hides the whole submenu; nothing is deleted.' } else { 'Turning it off sets LegacyDisable; nothing is deleted.' } }
        'Extension' { 'Turning it off adds the handler to the Blocked list. Applies after Explorer restarts.' }
        'New' { 'Turning it off renames its ShellNew key to _ShellNew; nothing is deleted.' }
        'SendTo' { if ($it.Submenu) { 'Turning it off hides the whole submenu folder; nothing is deleted.' } else { 'Turning it off hides the shortcut file; nothing is deleted.' } }
        default { 'Turning it off adds it to the Blocked list. Applies after Explorer restarts.' }
    }
    $U.DetailFields.ItemsSource = Get-EntryDetails $it
    $U.BtnEdit.Visibility = if ($it.CanEdit) { 'Visible' } else { 'Collapsed' }
    $U.BtnDelete.Visibility = if ($it.CanDelete) { 'Visible' } else { 'Collapsed' }
    $U.BtnDelete.Content = if ($it.Broken) { 'Remove' } else { 'Delete' }
    # Without an Edit button, let Delete take the whole row instead of sitting in the right half.
    [System.Windows.Controls.Grid]::SetColumn($U.BtnDelete, $(if ($it.CanEdit) { 2 } else { 0 }))
    [System.Windows.Controls.Grid]::SetColumnSpan($U.BtnDelete, $(if ($it.CanEdit) { 1 } else { 3 }))
    $U.BtnRegedit.Visibility = if ($it.CanRegedit) { 'Visible' } else { 'Collapsed' }
    $U.BtnRegedit.Content = if ($it.Kind -eq 'SendTo') { 'Show in folder' } else { 'Open in Regedit' }
    $U.BtnAddSendTo.Visibility = if (Test-CanSendTo $it) { 'Visible' } else { 'Collapsed' }
    $U.BtnCopy.Visibility = if ($it.Command) { 'Visible' } else { 'Collapsed' }
}

function Invoke-Refresh([switch]$Rescan, [string]$SelectId) {
    $selId = if ($SelectId) { $SelectId } elseif ($U.ItemList.SelectedItem) { $U.ItemList.SelectedItem.Id } else { $null }
    $sv = Find-VisualChild $U.ItemList ([System.Windows.Controls.ScrollViewer])
    $offset = if ($sv) { $sv.VerticalOffset } else { 0 }

    if ($Rescan) {
        $Window.Cursor = [System.Windows.Input.Cursors]::Wait
        try { Invoke-Scan } finally { $Window.Cursor = $null }
    }
    Update-View

    if ($selId) {
        $match = $App.View | Where-Object { $_.Id -eq $selId } | Select-Object -First 1
        if ($match) { $U.ItemList.SelectedItem = $match }
    }
    if ($sv) {
        $U.ItemList.UpdateLayout()
        $sv.ScrollToVerticalOffset($offset)
    }
    if ($SelectId -and $U.ItemList.SelectedItem) { $U.ItemList.ScrollIntoView($U.ItemList.SelectedItem) }
    Update-Detail
}

# ------------------------------------------------------------------------------
# Undo: one level, shown as a button in the status bar after each change.
# 'toggle' records flip a switch back; 'restore' records delete what the change created
# and re-import the backups taken before it.
# ------------------------------------------------------------------------------
function Set-Undo([hashtable]$Record) {
    $App.Undo = $Record
    $U.BtnUndo.Visibility = if ($Record) { 'Visible' } else { 'Collapsed' }
    $U.BtnUndo.ToolTip = if ($Record) { "Undo: $($Record.Label)" } else { $null }
}

function Get-IdPath([string]$Id) {
    # "cmd|HKCU|Software\Classes\...\shell\Key" -> @{ Hive; SubPath }
    $parts = $Id.Split('|', 3)
    return @{ Hive = $parts[1]; SubPath = $parts[2] }
}

function Invoke-Undo {
    $r = $App.Undo
    if (-not $r) { return }
    Set-Undo $null
    if ($r.Type -eq 'tweaks') {
        Invoke-Tweaks $r.Ids -Undo:$r.Revert -NoUndo
        Set-Status "Undone: $($r.Label)."
        return
    }
    if ($r.Type -eq 'toggle') {
        Invoke-Scan
        $items = foreach ($t in $r.Items) { $App.Items | Where-Object { $_.Id -eq $t.Id } | Select-Object -First 1 }
        $states = @{}
        foreach ($t in $r.Items) { $states[$t.Id] = $t.Enable }
        Invoke-SetEnabled @($items | Where-Object { $_ }) $states -NoUndo
        Set-Status "Undone: $($r.Label)."
        return
    }
    $needsAdmin = [bool]($r.DeletePaths | Where-Object { $_.Hive -eq 'HKLM' }) -or $r.NeedsAdmin
    $ok = Invoke-Write $(if ($needsAdmin) { 'HKLM' } else { 'HKCU' }) {
        foreach ($d in $r.DeletePaths) { Remove-RegTree $d.Hive $d.SubPath }
        foreach ($m in $r.Moves) { if (Test-Path -LiteralPath $m.To) { Move-Item -LiteralPath $m.To -Destination $m.From -Force } }
        foreach ($f in $r.DeleteFiles) { Remove-Item -LiteralPath $f -Recurse -Force -ErrorAction SilentlyContinue }
        foreach ($f in $r.Files) { [void](Restore-BackupFile $f) }
    }
    if ($ok) {
        Set-Status "Undone: $($r.Label)."
        if ($r.Pending) { Set-PendingRestart }
    }
    Invoke-Refresh -Rescan
    if ($App.Nav -eq 'backups') { Update-Backups }
}

# Turns entries on or off. $Enable is a bool for all of them, or a hashtable Id -> bool (used by Undo).
# All-users entries are skipped (with an offer to restart as admin) when not elevated; the rest still apply.
function Invoke-SetEnabled([object[]]$Items, $Enable, [switch]$NoUndo) {
    $Items = @($Items | Where-Object { $_ })
    if (-not $Items) { return }
    $want = { param($it) if ($Enable -is [hashtable]) { [bool]$Enable[$it.Id] } else { [bool]$Enable } }
    $todo = @($Items | Where-Object { $App.IsAdmin -or (Get-RequiredHive $_ (& $want $_)) -ne 'HKLM' })
    $skipped = $Items.Count - $todo.Count
    $done = [System.Collections.Generic.List[object]]::new()
    $ok = Invoke-Write 'HKCU' {
        foreach ($it in $todo) {
            $on = & $want $it
            Set-EntryEnabled $it $on
            $done.Add(@{ Id = $it.Id; Enable = -not $on })
        }
    }
    if ($done.Count) {
        $first = $todo[0]
        $verb = if (& $want $first) { 'turned on' } else { 'turned off' }
        $label = if ($done.Count -eq 1) { "$($first.Name) $verb" } else { "$($done.Count) entries changed" }
        Set-Status "$label."
        if ($todo | Where-Object { $_.Kind -notin 'Command', 'SendTo' }) { Set-PendingRestart }
        if (-not $NoUndo) { Set-Undo @{ Type = 'toggle'; Items = $done.ToArray(); Label = $label } }
    }
    Invoke-Refresh -Rescan
    if ($skipped) { [void](Invoke-Write 'HKLM' {}) }
}

function Invoke-Toggle($Item, [bool]$Enable, [switch]$NoUndo) {
    if (-not $Item) { return }
    Invoke-SetEnabled @($Item) $Enable -NoUndo:$NoUndo
}

function Invoke-Delete([object[]]$Items) {
    $Items = @($Items | Where-Object { $_ -and $_.CanDelete })
    if (-not $Items) { return }
    $one = $Items[0]
    if ($Items.Count -eq 1) {
        $text = if ($one.Kind -eq 'Extension') {
            'This shell extension is broken, so only its leftover registration is removed. A .reg backup is saved first.'
        } elseif ($one.Kind -eq 'SendTo') {
            'The shortcut is moved to the Backups folder, so you can undo or restore it.'
        } elseif ($one.Submenu -and $one.Children) {
            "The submenu and the $($one.Children) command$(if ($one.Children -ne 1) { 's' }) inside it are removed. A .reg backup is saved first, and you can undo or restore it from Backups."
        } else {
            'The registry key is removed. A .reg backup is saved first, and you can undo or restore it from Backups.'
        }
        $verb = if ($one.Broken) { 'Remove' } else { 'Delete' }
        $title = "$verb `"$($one.Name)`"?"
    } else {
        $list = ($Items | Select-Object -First 8 | ForEach-Object { "  $($_.Name)" }) -join "`n"
        if ($Items.Count -gt 8) { $list += "`n  ...and $($Items.Count - 8) more" }
        $text = "$list`n`nEach one is backed up first, so this can be undone."
        $verb = 'Delete'
        $title = "Delete $($Items.Count) entries?"
    }
    $r = Show-Message -Title $title -Text $text -Buttons @('Cancel', $verb) -Primary $verb -Danger
    if ($r -ne $verb) { return }

    $todo = @($Items | Where-Object { $App.IsAdmin -or $_.Hive -ne 'HKLM' })
    $skipped = $Items.Count - $todo.Count
    $files = [System.Collections.Generic.List[string]]::new()
    $ok = Invoke-Write 'HKCU' { foreach ($it in $todo) { $files.AddRange([string[]](Remove-MenuEntry $it)) } }
    if ($files.Count) {
        $label = if ($todo.Count -eq 1) { "deleted $($todo[0].Name)" } else { "deleted $($todo.Count) entries" }
        Set-Status "$($label.Substring(0,1).ToUpper())$($label.Substring(1)). Backup saved."
        $pending = [bool]($todo | Where-Object { $_.Kind -notin 'Command', 'SendTo' })
        Set-Undo @{ Type = 'restore'; Files = $files.ToArray(); DeletePaths = @(); NeedsAdmin = [bool]($todo | Where-Object Hive -eq 'HKLM')
                    Pending = $pending; Label = $label }
        if ($pending) { Set-PendingRestart }
    }
    Invoke-Refresh -Rescan
    if ($skipped) { [void](Invoke-Write 'HKLM' {}) }
}

function Invoke-CleanupBroken {
    $items = @($App.Items | Where-Object { $_.Broken -and $_.CanDelete })
    if (-not $items) { return }
    $list = ($items | Select-Object -First 8 | ForEach-Object { "  $($_.Name)" }) -join "`n"
    if ($items.Count -gt 8) { $list += "`n  ...and $($items.Count - 8) more" }
    $r = Show-Message -Title "Remove $($items.Count) broken entr$(if ($items.Count -eq 1) { 'y' } else { 'ies' })?" `
        -Text "These point to programs that are no longer installed:`n$list`n`nEach one is backed up first, so this can be undone." `
        -Buttons @('Cancel', 'Remove all') -Primary 'Remove all' -Danger
    if ($r -ne 'Remove all') { return }

    # Per-user ones never need admin; all-users ones only when we have it.
    $doable = @($items | Where-Object { $App.IsAdmin -or $_.Hive -ne 'HKLM' })
    $skipped = $items.Count - $doable.Count
    $files = [System.Collections.Generic.List[string]]::new()
    $ok = Invoke-Write 'HKCU' { foreach ($it in $doable) { $files.AddRange([string[]](Remove-MenuEntry $it)) } }
    if ($ok -and $doable.Count) {
        Set-Status "Removed $($doable.Count) broken entr$(if ($doable.Count -eq 1) { 'y' } else { 'ies' }). Backups saved."
        Set-Undo @{ Type = 'restore'; Files = $files.ToArray(); DeletePaths = @(); NeedsAdmin = [bool]($doable | Where-Object Hive -eq 'HKLM')
                    Pending = [bool]($doable | Where-Object Kind -ne 'Command'); Label = 'broken entry cleanup' }
        if ($doable | Where-Object Kind -ne 'Command') { Set-PendingRestart }
    }
    Invoke-Refresh -Rescan
    if ($skipped) { [void](Invoke-Write 'HKLM' {}) }
}

# ------------------------------------------------------------------------------
# Backups view
# ------------------------------------------------------------------------------
function Update-Backups {
    $list = @(Get-Backups)
    $U.BackupList.ItemsSource = $list
    $U.BackupsEmpty.Visibility = if ($list.Count) { 'Collapsed' } else { 'Visible' }
    $U.TxtSubtitle.Text = "$($NavText.backups[1])  /  $($list.Count) file$(if ($list.Count -ne 1) { 's' })"
    ($NavEntries | Where-Object Id -eq 'backups').Count = [string]$list.Count
}

function Invoke-RestoreBackup($Rec) {
    if (-not $Rec) { return }
    if ($Rec.IsFull) {
        $text = 'Adds back every entry in this file. Entries created since are kept and nothing is deleted. A full backup of the current state is saved first.'
    } else {
        $text = "Puts `"$($Rec.Name)`" back exactly as it was ($($Rec.WhenText)). If it exists now, the current version is backed up and then replaced."
    }
    $r = Show-Message -Title "Restore `"$($Rec.Name)`"?" -Text $text -Buttons @('Cancel', 'Restore') -Primary 'Restore'
    if ($r -ne 'Restore') { return }

    # Keys that don't exist yet are what Undo has to delete again.
    $created = @()
    foreach ($root in $Rec.Roots) {
        $p = Split-RegPath $root
        if (-not $p) { continue }
        $k = (Get-HiveRoot $p.Hive).OpenSubKey($p.SubPath)
        if ($k) { $k.Close() } else { $created += $p }
    }
    $pre = [System.Collections.Generic.List[string]]::new()
    $ok = Invoke-Write $(if ($Rec.NeedsAdmin) { 'HKLM' } else { 'HKCU' }) {
        if ($Rec.IsFull) {
            [void](Export-FullBackup)
            [void](Restore-BackupFile $Rec.File -Merge)
        } else {
            $pre.AddRange([string[]](Restore-BackupFile $Rec.File))
        }
    }
    if ($ok) {
        Set-Status "Restored `"$($Rec.Name)`"."
        $touchesExt = [bool]($Rec.Roots | Where-Object { $_ -match '\\shellex\\|Shell Extensions' })
        if ($touchesExt) { Set-PendingRestart }
        if (-not $Rec.IsFull -and $Rec.Roots.Count) {
            Set-Undo @{ Type = 'restore'; Files = $pre.ToArray(); DeletePaths = $created; NeedsAdmin = $Rec.NeedsAdmin
                        Pending = $touchesExt; Label = "restore of $($Rec.Name)" }
        }
    }
    Invoke-Scan
    Update-View
    Update-Backups
}

function Invoke-DeleteBackupFile($Rec) {
    if (-not $Rec) { return }
    $r = Show-Message -Title 'Delete this backup file?' -Text "$($Rec.FileName)`n`nThe registry is not changed; only the .reg file is removed." `
        -Buttons @('Cancel', 'Delete file') -Primary 'Delete file' -Danger
    if ($r -ne 'Delete file') { return }
    Remove-Item -LiteralPath $Rec.File -Recurse -Force -ErrorAction SilentlyContinue
    Update-Backups
}

# ------------------------------------------------------------------------------
# Add / edit dialog (commands and submenus)
# ------------------------------------------------------------------------------
function Show-Editor($Existing, $Parent) {
    $w = New-Window $EditorXaml
    $w.Owner = $Window
    $w.MaxHeight = [System.Windows.SystemParameters]::WorkArea.Height - 40
    $c = @{}
    foreach ($n in 'EdTitle', 'EdSubtitle', 'EdModeRow', 'EdModeCmd', 'EdModeSub', 'EdName', 'EdCommandSection', 'EdCommand', 'EdBrowseExe',
                   'EdTok1', 'EdTokV', 'EdIcon', 'EdIconPreview', 'EdBrowseIcon', 'EdLocFiles', 'EdLocFolders', 'EdLocBackground',
                   'EdLocDesktop', 'EdLocDrives', 'EdLocAll', 'EdLocType', 'EdLocOther', 'EdExt', 'EdScopeUser', 'EdScopeAll',
                   'EdGroupSection', 'EdGroups', 'EdGroupHint', 'EdShift', 'EdShield', 'EdPosDefault', 'EdPosTop', 'EdPosBottom',
                   'EdError', 'EdCancel', 'EdSave', 'EdTest') {
        $c[$n] = $w.FindName($n)
    }
    $locMap = [ordered]@{ EdLocFiles = '*'; EdLocFolders = 'Directory'; EdLocBackground = 'Directory\Background'; EdLocDesktop = 'DesktopBackground'; EdLocDrives = 'Drive'; EdLocAll = 'AllFilesystemObjects' }
    $result = @{ Id = $null }
    $state = @{ Group = if ($Existing) { $Existing.ParentPath } elseif ($Parent) { $Parent.SubPath } else { '' } }

    $updatePreview = {
        $spec = if ($c.EdIcon.Text.Trim()) { $c.EdIcon.Text.Trim() } else { Get-ExeFromCommand $c.EdCommand.Text }
        $c.EdIconPreview.Source = Get-IconImage $spec
    }
    $c.EdIcon.Add_TextChanged($updatePreview)
    $c.EdCommand.Add_TextChanged($updatePreview)

    # '' when no valid location is chosen
    $getBase = {
        foreach ($k in $locMap.Keys) { if ($c[$k].IsChecked) { return $locMap[$k] } }
        if ($c.EdLocType.IsChecked) {
            $ext = $c.EdExt.Text.Trim().TrimStart('.').ToLowerInvariant()
            if ($ext -and $ext -notmatch '[^a-z0-9_+-]') { return "SystemFileAssociations\.$ext" }
            return ''
        }
        if ($c.EdLocOther.IsChecked -and $Existing) { return $Existing.BaseKey }
        return ''
    }

    $isSubmenuMode = { if ($Existing) { [bool]$Existing.Submenu } else { [bool]$c.EdModeSub.IsChecked } }

    # Submenus the command can go into: same location and scope, editable, top level.
    $refreshGroups = {
        $checked = $c.EdGroups.Children | Where-Object { $_.IsChecked } | Select-Object -First 1
        if ($checked) { $state.Group = [string]$checked.Tag }
        $c.EdGroups.Children.Clear()
        $base = & $getBase
        $hive = if ($c.EdScopeAll.IsChecked) { 'HKLM' } else { 'HKCU' }
        $groups = @($App.Items | Where-Object {
            $_.Kind -eq 'Command' -and $_.Submenu -and $_.CanEdit -and -not $_.ParentName -and $_.BaseKey -eq $base -and
            $_.Hive -eq $hive -and (-not $Existing -or $_.Id -ne $Existing.Id)
        } | Sort-Object Name)
        $choices = @(@{ Label = 'Not in a submenu'; Tag = '' }) + @($groups | ForEach-Object { @{ Label = $_.Name; Tag = $_.SubPath } })
        $matched = $false
        foreach ($ch in $choices) {
            $rb = [System.Windows.Controls.RadioButton]::new()
            $rb.Style = $w.FindResource('Chip')
            $rb.GroupName = 'grp'
            $rb.Content = $ch.Label
            $rb.Tag = $ch.Tag
            if ($ch.Tag -eq $state.Group) { $rb.IsChecked = $true; $matched = $true }
            [void]$c.EdGroups.Children.Add($rb)
        }
        if (-not $matched) { $c.EdGroups.Children[0].IsChecked = $true }
        $c.EdGroupHint.Visibility = if ($groups.Count) { 'Collapsed' } else { 'Visible' }
    }

    $applyMode = {
        $sub = & $isSubmenuMode
        $c.EdCommandSection.Visibility = if ($sub) { 'Collapsed' } else { 'Visible' }
        $c.EdGroupSection.Visibility = if ($sub) { 'Collapsed' } else { 'Visible' }
        if (-not $Existing) {
            $c.EdTitle.Text = if ($sub) { 'New submenu' } else { 'New command' }
            $w.Title = $c.EdTitle.Text
            $c.EdSubtitle.Text = if ($sub) { 'Groups several commands under one entry. Add commands to it with "New command".' }
                                 else { 'Runs a program when you pick it from the right-click menu.' }
            $c.EdSave.Content = if ($sub) { 'Add submenu' } else { 'Add command' }
            $c.EdName.Tag = if ($sub) { 'Text shown in the menu, e.g. Dev tools' } else { 'Text shown in the menu, e.g. Open with Notepad++' }
        }
    }
    $c.EdModeCmd.Add_Checked($applyMode)
    $c.EdModeSub.Add_Checked($applyMode)

    $selectBase = {
        param([string]$Base)
        foreach ($k in $locMap.Keys) { if ($locMap[$k] -eq $Base) { $c[$k].IsChecked = $true; return } }
        if ($Base -like 'SystemFileAssociations\.*') {
            $c.EdLocType.IsChecked = $true
            $c.EdExt.Text = $Base.Substring(23)
            return
        }
        $c.EdLocOther.Content = "Current: $Base"
        $c.EdLocOther.Visibility = 'Visible'
        $c.EdLocOther.IsChecked = $true
    }

    if ($Existing) {
        $kindWord = if ($Existing.Submenu) { 'submenu' } else { 'command' }
        $w.Title = "Edit $kindWord"
        $c.EdTitle.Text = "Edit $kindWord"
        $c.EdSubtitle.Text = "Changes are written to $($Existing.Hive)\$($Existing.SubPath). A backup is saved first."
        $c.EdModeRow.Visibility = 'Collapsed'
        $c.EdName.Text = $Existing.Name
        $c.EdCommand.Text = $Existing.Command
        $c.EdIcon.Text = $Existing.IconValue
        $c.EdShift.IsChecked = [bool]$Existing.Extended
        $c.EdShield.IsChecked = [bool]$Existing.Shield
        switch ($Existing.Position) { 'Top' { $c.EdPosTop.IsChecked = $true } 'Bottom' { $c.EdPosBottom.IsChecked = $true } }
        if ($Existing.Hive -eq 'HKLM') { $c.EdScopeAll.IsChecked = $true }
        & $selectBase $Existing.BaseKey
        $c.EdSave.Content = 'Save changes'
    } else {
        $navBase = @{ files = '*'; folders = 'Directory'; background = 'Directory\Background'; desktop = 'DesktopBackground'; drives = 'Drive' }
        if ($Parent) {
            if ($Parent.Hive -eq 'HKLM') { $c.EdScopeAll.IsChecked = $true }
            & $selectBase $Parent.BaseKey
        }
        elseif ($App.Nav -eq 'filetypes') { $c.EdLocType.IsChecked = $true; $c.EdExt.Text = $App.Ext }
        elseif ($navBase.ContainsKey($App.Nav)) { & $selectBase $navBase[$App.Nav] }
        else { $c.EdLocFiles.IsChecked = $true }
    }
    & $applyMode
    & $refreshGroups
    foreach ($k in @($locMap.Keys) + 'EdLocType', 'EdLocOther', 'EdScopeUser', 'EdScopeAll') { $c[$k].Add_Checked($refreshGroups) }
    $c.EdExt.Add_TextChanged($refreshGroups)
    $c.EdLocType.Add_Checked({ $c.EdExt.Visibility = 'Visible'; $c.EdExt.Focus() })
    $c.EdLocType.Add_Unchecked({ $c.EdExt.Visibility = 'Collapsed' })
    if ($c.EdLocType.IsChecked) { $c.EdExt.Visibility = 'Visible' }
    if (-not $App.IsAdmin -and -not $c.EdScopeAll.IsChecked) { $c.EdScopeAll.ToolTip = 'Restart the editor as administrator to install for all users' }

    $insertToken = {
        param([string]$Token)
        $tb = $c.EdCommand
        $text = "`"$Token`""
        $pos = $tb.CaretIndex
        if ($pos -gt 0 -and $tb.Text[$pos - 1] -ne ' ') { $text = " $text" }
        $tb.Text = $tb.Text.Insert($pos, $text)
        $tb.CaretIndex = $pos + $text.Length
        $tb.Focus()
    }
    $c.EdTok1.Add_Click({ & $insertToken '%1' })
    $c.EdTokV.Add_Click({ & $insertToken '%V' })

    $c.EdBrowseExe.Add_Click({
        $dlg = [System.Windows.Forms.OpenFileDialog]::new()
        $dlg.Filter = 'Programs (*.exe;*.bat;*.cmd)|*.exe;*.bat;*.cmd|All files (*.*)|*.*'
        $dlg.Title = 'Choose the program to run'
        if ($dlg.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) {
            $token = if ($c.EdLocBackground.IsChecked -or $c.EdLocDesktop.IsChecked) { '%V' } else { '%1' }
            $c.EdCommand.Text = "`"$($dlg.FileName)`" `"$token`""
            if (-not $c.EdName.Text.Trim()) {
                $desc = try { [Diagnostics.FileVersionInfo]::GetVersionInfo($dlg.FileName).FileDescription } catch { '' }
                if (-not $desc) { $desc = [IO.Path]::GetFileNameWithoutExtension($dlg.FileName) }
                $c.EdName.Text = "Open with $desc"
            }
        }
    })
    $c.EdTest.Add_Click({
        $c.EdError.Foreground = $w.FindResource('Danger')
        $c.EdError.Text = ''
        $command = $c.EdCommand.Text.Trim()
        if (-not $command) { $c.EdError.Text = 'Enter a command to test.'; $c.EdCommand.Focus(); return }
        # Pick a sample like the one Explorer would pass for this location.
        $base = & $getBase
        $sample = $null
        if ($base -eq 'DesktopBackground') {
            $sample = [Environment]::GetFolderPath('Desktop')
        } elseif ($base -in 'Directory', 'Directory\Background', 'Drive', 'Folder') {
            $dlg = [System.Windows.Forms.FolderBrowserDialog]::new()
            $dlg.Description = 'Pick a folder to test the command on'
            if ($dlg.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) { $sample = $dlg.SelectedPath }
        } else {
            $dlg = [System.Windows.Forms.OpenFileDialog]::new()
            $dlg.Title = 'Pick a file to test the command on'
            if ($base -like 'SystemFileAssociations\.*') { $e = $base.Substring(23); $dlg.Filter = "$e files (*$e)|*$e|All files (*.*)|*.*" }
            if ($dlg.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) { $sample = $dlg.FileName }
        }
        if (-not $sample) { return }
        try {
            $ran = Invoke-TestCommand $command $sample
            $c.EdError.Foreground = $w.FindResource('Success')
            $c.EdError.Text = "Started: $ran"
        } catch {
            $c.EdError.Text = "Could not run it: $($_.Exception.InnerException.Message)$(if (-not $_.Exception.InnerException) { $_.Exception.Message })"
        }
    })
    $c.EdBrowseIcon.Add_Click({
        $dlg = [System.Windows.Forms.OpenFileDialog]::new()
        $dlg.Filter = 'Icons (*.ico;*.exe;*.dll)|*.ico;*.exe;*.dll|All files (*.*)|*.*'
        $dlg.Title = 'Choose an icon'
        if ($dlg.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) { $c.EdIcon.Text = $dlg.FileName }
    })

    $c.EdSave.Add_Click({
        $c.EdError.Foreground = $w.FindResource('Danger')
        $c.EdError.Text = ''
        $isSub = & $isSubmenuMode
        $name = $c.EdName.Text.Trim()
        $command = $c.EdCommand.Text.Trim()
        if (-not $name) { $c.EdError.Text = 'Give it a name.'; $c.EdName.Focus(); return }
        if (-not $isSub -and -not $command -and -not ($Existing -and $Existing.Delegate)) { $c.EdError.Text = 'Enter the command to run.'; $c.EdCommand.Focus(); return }

        $base = & $getBase
        if (-not $base) {
            if ($c.EdLocType.IsChecked) { $c.EdError.Text = 'Enter a file extension such as .pdf'; $c.EdExt.Focus() }
            else { $c.EdError.Text = 'Choose where it appears.' }
            return
        }
        $hive = if ($c.EdScopeAll.IsChecked) { 'HKLM' } else { 'HKCU' }
        if ($hive -eq 'HKLM' -and -not $App.IsAdmin) { $c.EdError.Text = 'Installing for all users needs administrator rights. Use the card at the bottom of the sidebar to restart as admin.'; return }
        $position = if ($c.EdPosTop.IsChecked) { 'Top' } elseif ($c.EdPosBottom.IsChecked) { 'Bottom' } else { '' }
        $group = if ($isSub) { '' } else { [string]($c.EdGroups.Children | Where-Object { $_.IsChecked } | Select-Object -First 1).Tag }
        $shellPath = if ($group) { "$group\shell" } else { "Software\Classes\$base\shell" }

        try {
            $result.Id = Save-MenuCommand -Existing $Existing -Name $name -Command $command -Icon $c.EdIcon.Text.Trim() `
                -Hive $hive -ShellPath $shellPath -Extended ([bool]$c.EdShift.IsChecked) -Shield ([bool]$c.EdShield.IsChecked) `
                -Position $position -IsSubmenu $isSub
            $w.DialogResult = $true
        } catch {
            $c.EdError.Text = "Could not save: $($_.Exception.Message)"
        }
    })

    $w.Add_ContentRendered({ $c.EdName.Focus(); $c.EdName.SelectAll() })
    & $updatePreview
    [void]$w.ShowDialog()
    return $result.Id
}

function Invoke-Edit($Item) {
    if ($Item -and -not $Item.CanEdit) { return }
    if ($Item -and $Item.Hive -eq 'HKLM' -and -not $App.IsAdmin) {
        [void](Invoke-Write 'HKLM' {})
        return
    }
    # "New command" while a submenu is selected starts inside that submenu.
    $sel = $U.ItemList.SelectedItem
    $parent = if (-not $Item -and $sel -and $sel.Submenu -and $sel.CanEdit -and -not $sel.ParentName) { $sel } else { $null }
    $id = Show-Editor $Item $parent
    if (-not $id) { return }

    $newPath = Get-IdPath $id
    if ($Item) {
        Set-Status "Saved changes to `"$($Item.Name)`"."
        Set-Undo @{ Type = 'restore'; Files = @($App.LastBackup); DeletePaths = @($newPath); NeedsAdmin = $Item.Hive -eq 'HKLM'
                    Pending = $false; Label = "edit of $($Item.Name)" }
    } else {
        Set-Status 'Added. Right-click something to try it.'
        Set-Undo @{ Type = 'restore'; Files = @(); DeletePaths = @($newPath); NeedsAdmin = $false; Pending = $false; Label = 'adding the entry' }
    }
    Invoke-Refresh -Rescan -SelectId $id
}

function Invoke-AddNewType {
    $ext = $U.TxtNewExt.Text.Trim()
    if (-not $ext) { $U.TxtNewExt.Focus(); return }
    $result = @{}
    try {
        # Decide the hive up front so non-admins get the restart offer instead of an access error.
        $e = '.' + $ext.TrimStart('.').ToLowerInvariant()
        $userKey = [Microsoft.Win32.Registry]::CurrentUser.OpenSubKey("Software\Classes\$e")
        $hive = if ($userKey) { $userKey.Close(); 'HKCU' } else { 'HKLM' }
        $ok = Invoke-Write $hive { $r = Add-ShellNewType $ext; $result.Hive = $r.Hive; $result.SubPath = $r.SubPath }
    } catch { $ok = $false; [void](Show-Message -Title 'Could not add it' -Text $_.Exception.Message) }
    if ($ok -and $result.SubPath) {
        $U.TxtNewExt.Text = ''
        Set-Status "Added $e to the New menu."
        Set-Undo @{ Type = 'restore'; Files = @(); DeletePaths = @(@{ Hive = $result.Hive; SubPath = $result.SubPath }); NeedsAdmin = $result.Hive -eq 'HKLM'; Pending = $true; Label = "adding $e" }
        Set-PendingRestart
        Invoke-Refresh -Rescan -SelectId "new|$($result.Hive)|$e"
    }
}

function Invoke-AddSendTo([switch]$Folder) {
    $target = $null
    if ($Folder) {
        $dlg = [System.Windows.Forms.FolderBrowserDialog]::new()
        $dlg.Description = 'Choose the folder to send files to'
        if ($dlg.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) { $target = $dlg.SelectedPath }
    } else {
        $dlg = [System.Windows.Forms.OpenFileDialog]::new()
        $dlg.Filter = 'Programs (*.exe;*.bat;*.cmd)|*.exe;*.bat;*.cmd|All files (*.*)|*.*'
        $dlg.Title = 'Choose the program to send files to'
        if ($dlg.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) { $target = $dlg.FileName }
    }
    if (-not $target) { return }
    try {
        $path = Add-SendToShortcut $target
        Set-Status "Added `"$([IO.Path]::GetFileNameWithoutExtension($path))`" to Send to."
        Set-Undo @{ Type = 'restore'; Files = @(); DeletePaths = @(); DeleteFiles = @($path); Label = 'adding the Send to shortcut' }
        Invoke-Refresh -Rescan -SelectId "sendto|$([IO.Path]::GetFileName($path))"
    } catch {
        [void](Show-Message -Title 'Could not add it' -Text $_.Exception.Message)
    }
}

function Invoke-ExportSetup {
    $dlg = [System.Windows.Forms.SaveFileDialog]::new()
    $dlg.Filter = 'Registry file (*.reg)|*.reg'
    $dlg.FileName = "context-menu-setup-$(Get-Date -Format 'yyyy-MM-dd').reg"
    $dlg.Title = 'Export your context menu setup'
    if ($dlg.ShowDialog() -ne [System.Windows.Forms.DialogResult]::OK) { return }
    try {
        $n = Export-Setup $dlg.FileName
        Set-Status "Exported $n registry keys to $(Split-Path -Leaf $dlg.FileName)."
    } catch {
        [void](Show-Message -Title 'Export failed' -Text $_.Exception.Message)
    }
}

function Invoke-ImportSetup {
    $dlg = [System.Windows.Forms.OpenFileDialog]::new()
    $dlg.Filter = 'Registry file (*.reg)|*.reg'
    $dlg.Title = 'Import a context menu setup'
    if ($dlg.ShowDialog() -ne [System.Windows.Forms.DialogResult]::OK) { return }
    $info = Get-BackupInfo ([IO.FileInfo]::new($dlg.FileName))
    $outside = @($info.Roots | Where-Object { $_ -notmatch '\\Software\\Classes\\|Shell Extensions\\Blocked' })
    $text = "Adds the $($info.Roots.Count) registry key$(if ($info.Roots.Count -ne 1) { 's' }) in this file to your registry. Nothing is deleted, and a full backup of your current menus is saved first."
    if ($outside) { $text += "`n`nWarning: this file also touches keys outside the context menu, for example:`n  $($outside[0])" }
    $r = Show-Message -Title "Import $(Split-Path -Leaf $dlg.FileName)?" -Text $text -Buttons @('Cancel', 'Import') -Primary 'Import'
    if ($r -ne 'Import') { return }
    $ok = Invoke-Write $(if ($info.NeedsAdmin) { 'HKLM' } else { 'HKCU' }) {
        [void](Export-FullBackup)
        [void](Restore-BackupFile $dlg.FileName -Merge)
    }
    if ($ok) {
        Set-Status 'Setup imported. A full backup of the previous state is in Backups.'
        Set-PendingRestart
    }
    Invoke-Scan
    Update-View
    if ($App.Nav -eq 'backups') { Update-Backups }
}

# Runs a command line the way Explorer would, with %1/%V/%L/%W replaced by a sample path.
function Invoke-TestCommand([string]$Command, [string]$SamplePath) {
    $line = [Environment]::ExpandEnvironmentVariables($Command.Trim())
    $line = [regex]::Replace($line, '%[1LVWlvw*]', [System.Text.RegularExpressions.MatchEvaluator] { param($m) $SamplePath })
    $exe = Get-ExeFromCommand $line
    $rest = if ($line.StartsWith('"')) { $line.Substring($exe.Length + 2) } else { $line.Substring($exe.Length) }
    $psi = [Diagnostics.ProcessStartInfo]::new($exe, $rest.Trim())
    $psi.UseShellExecute = $true
    $psi.WorkingDirectory = if (Test-Path -LiteralPath $SamplePath -PathType Container) { $SamplePath } else { Split-Path -Parent $SamplePath }
    [void][Diagnostics.Process]::Start($psi)
    return "$exe $($rest.Trim())"
}

function Open-InRegedit($Item) {
    if ($Item -and $Item.Kind -eq 'SendTo') {
        Start-Process explorer.exe -ArgumentList "/select,`"$($Item.FilePath)`""
        return
    }
    if (-not $Item -or -not $Item.SubPath) { return }
    $hive = if ($Item.Hive -eq 'HKLM') { 'HKEY_LOCAL_MACHINE' } else { 'HKEY_CURRENT_USER' }
    $k = [Microsoft.Win32.Registry]::CurrentUser.CreateSubKey('Software\Microsoft\Windows\CurrentVersion\Applets\Regedit')
    try { $k.SetValue('LastKey', "Computer\$hive\$($Item.SubPath)") } finally { $k.Close() }
    if (Get-Process regedit -ErrorAction SilentlyContinue) {
        Set-Status 'Registry Editor is already open; close it and try again so it jumps to this key.'
        return
    }
    try { Start-Process regedit.exe -ErrorAction Stop } catch { Set-Status 'Registry Editor was not opened.' }
}

function Restart-Explorer {
    Set-Status 'Restarting Explorer...'
    $U.PendingBar.Visibility = 'Collapsed'
    Get-Process explorer -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
    # Windows normally restarts the shell by itself; start it only if it didn't come back.
    $timer = [System.Windows.Threading.DispatcherTimer]::new()
    $timer.Interval = [TimeSpan]::FromMilliseconds(2500)
    $timer.Add_Tick({
        param($sender)
        $sender.Stop()
        if (-not (Get-Process explorer -ErrorAction SilentlyContinue)) { Start-Process explorer.exe }
        Set-Status 'Explorer restarted. Menus are reloaded.'
    })
    $timer.Start()
}

# ------------------------------------------------------------------------------
# Tweaks page: a checklist. Check tweaks (or pick a preset), then "Run tweaks";
# "Undo selected" writes the original values back. Toggle tweaks apply as soon as they're switched.
# ------------------------------------------------------------------------------
function Update-Tweaks {
    $keep = @{}
    foreach ($i in @($U.TweakList.ItemsSource)) { if ($i -and $i.Kind -eq 'check' -and $i.Checked) { $keep[$i.Id] = $true } }

    $items = [System.Collections.Generic.List[object]]::new()
    $last = $null
    $applied = 0
    $defs = Get-TweakDefinitions
    foreach ($t in $defs) {
        if ($t.Category -ne $last) {
            $items.Add([pscustomobject]@{ Kind = 'header'; Id = ''; Title = $t.Category; Desc = ''; Applied = $false; Available = $true; Note = ''; ShowApplied = $false; Checked = $false })
            $last = $t.Category
        }
        $s = Get-TweakState $t
        if ($s.Applied) { $applied++ }
        $items.Add([pscustomobject]@{
            Kind = $(if ($t.IsToggle) { 'toggle' } else { 'check' }); Id = $t.Id; Title = $t.Content; Desc = $t.Description
            Applied = $s.Applied; Available = $s.Available; Note = $s.Note; ShowApplied = $s.Applied -and -not $t.IsToggle
            Checked = $keep.ContainsKey($t.Id) -and $s.Available
        })
    }
    $U.TweakList.ItemsSource = $items
    $U.TweakPresetList.ItemsSource = @((Get-TweakPresets).Keys)
    $U.TxtSubtitle.Text = "$($NavText.tweaks[1])  /  $applied of $($defs.Count) applied"
}

function Get-CheckedTweakIds { return @($U.TweakList.ItemsSource | Where-Object { $_.Kind -eq 'check' -and $_.Checked } | ForEach-Object Id) }

# Checks exactly the given tweaks (presets, Clear).
function Set-TweakChecks([string[]]$Ids) {
    foreach ($i in @($U.TweakList.ItemsSource)) { if ($i.Kind -eq 'check') { $i.Checked = $i.Available -and ($Ids -contains $i.Id) } }
    $U.TweakList.Items.Refresh()
}

# Runs (or with -Undo, reverts) tweaks. Only ones that would change something are touched, so the
# status line and the Undo button describe exactly what happened.
function Invoke-Tweaks([string[]]$Ids, [switch]$Undo, [switch]$NoUndo) {
    $defs = @(Get-TweakDefinitions | Where-Object { $Ids -contains $_.Id })
    if (-not $defs) { Set-Status 'Check the tweaks you want first, or pick a preset.'; return }
    if (-not $App.IsAdmin -and ($defs | Where-Object { Test-TweakNeedsAdmin $_ })) { [void](Invoke-Write 'HKLM' {}); return }

    $todo = @($defs | Where-Object { $s = Get-TweakState $_; $s.Available -and ($s.Applied -eq [bool]$Undo) })
    $skipped = $defs.Count - $todo.Count
    $done = [System.Collections.Generic.List[string]]::new()
    $errors = [System.Collections.Generic.List[string]]::new()
    $Window.Cursor = [System.Windows.Input.Cursors]::Wait
    try {
        foreach ($t in $todo) {
            try { Invoke-Tweak $t -Undo:$Undo; $done.Add($t.Id) }
            catch { $errors.Add("$($t.Content): $($_.Exception.Message)") }
        }
    } finally { $Window.Cursor = $null }

    $verb = if ($Undo) { 'Undid' } else { 'Applied' }
    $msg = "$verb $($done.Count) tweak$(if ($done.Count -ne 1) { 's' })"
    if ($skipped) { $msg += " ($skipped already $(if ($Undo) { 'not applied' } else { 'applied' }) or unavailable)" }
    Set-Status "$msg."
    if ($done.Count) {
        if ($todo | Where-Object { $done -contains $_.Id -and $_.RestartExplorer }) { Set-PendingRestart }
        if (-not $NoUndo) {
            Set-Undo @{ Type = 'tweaks'; Ids = $done.ToArray(); Revert = -not $Undo; Label = "$($verb.ToLower()) $($done.Count) tweak$(if ($done.Count -ne 1) { 's' })" }
        }
    }
    if ($errors.Count) { [void](Show-Message -Title 'Some tweaks did not apply' -Text ($errors -join "`n")) }
    Update-Tweaks
    Invoke-Scan
    Update-View
}

# ------------------------------------------------------------------------------
# About dialog: version, the launch command, where things live, and links.
# ------------------------------------------------------------------------------
function Show-About {
    $w = New-Window $AboutXaml
    if ($Window -and $Window.IsLoaded) { $w.Owner = $Window }
    $w.FindName('AboutIcon').Source = Get-AssetImage 'app-icon-64.png'
    $w.FindName('AboutWordmark').Source = Get-AssetImage 'wordmark.png'
    $w.FindName('AboutVersion').Text = "Version $AppVersion"
    $w.FindName('AboutLaunch').Text = $AppLaunchCommand

    $copy = $w.FindName('AboutCopy')
    $copy.Add_Click({
        try { [System.Windows.Clipboard]::SetText($AppLaunchCommand); $copy.Content = 'Copied' } catch {}
    })

    $ps = "$($PSVersionTable.PSVersion.Major).$($PSVersionTable.PSVersion.Minor)" + $(if ($PSVersionTable.PSEdition -eq 'Core') { '' } else { ' (Windows PowerShell)' })
    $facts = [ordered]@{
        'Running from' = $(if ($App.ScriptPath) { $App.ScriptPath } else { 'Downloaded with the launch command' })
        'Backups'      = $App.BackupDir
        'Running as'   = $(if ($App.IsAdmin) { 'Administrator' } else { 'Standard user' })
        'PowerShell'   = $ps
        'Windows'      = "Build $([Environment]::OSVersion.Version.Build)"
    }
    $grid = $w.FindName('AboutFacts')
    $row = 0
    foreach ($k in $facts.Keys) {
        $grid.RowDefinitions.Add([System.Windows.Controls.RowDefinition]::new())
        $label = [System.Windows.Controls.TextBlock]::new()
        $label.Text = $k; $label.Foreground = $w.FindResource('Faint'); $label.Margin = '0,3,12,3'
        $value = [System.Windows.Controls.TextBox]::new()
        $value.Style = $w.FindResource('ReadOnlyText'); $value.Text = $facts[$k]; $value.Margin = '0,3,0,3'
        [System.Windows.Controls.Grid]::SetRow($label, $row); [System.Windows.Controls.Grid]::SetRow($value, $row)
        [System.Windows.Controls.Grid]::SetColumn($value, 1)
        [void]$grid.Children.Add($label); [void]$grid.Children.Add($value)
        $row++
    }

    $w.FindName('AboutSource').Add_Click({ Start-Process $AppRepoUrl })
    $w.FindName('AboutSite').Add_Click({ Start-Process $AppSiteUrl })
    $w.FindName('AboutClose').Add_Click({ $w.Close() })
    [void]$w.ShowDialog()
}

